import subprocess, os, tempfile, pathlib, re
def run(args, cwd):
    p=subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, cwd=cwd, env={**os.environ,"HOME":str(pathlib.Path(cwd).parent)}, timeout=15)
    out=re.sub(r'^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d ', 'TS ', p.stdout, flags=re.M)
    err=re.sub(r'^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d ', 'TS ', p.stderr, flags=re.M)
    return p.returncode, out, err
def trial(label, files, cmds, cwd_rel="."):
    with tempfile.TemporaryDirectory() as td:
        root=pathlib.Path(td)
        for rel,content in files.items():
            p=root/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(content)
        cwd=root/cwd_rel
        print("\n===",label, "cwd",cwd_rel)
        for cmd in cmds:
            try:
                rc,out,err=run(cmd, str(cwd))
                print(cmd,"rc",rc,"out:",out[:1000], "err:",err[:3000])
            except Exception as e:
                print(cmd,"EXC",e)

