package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

var debugEnabled bool

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func logMsg(level, msg string) {
	// msg may contain newlines: original logger appears to emit one log line per call;
	// callers should pass single-line messages mostly. Multi-line (stack) handled by splitting in caller.
	ts := time.Now().Format("2006-01-02 15:04:05")
	label := level
	if isTTY(os.Stderr) {
		color := ""
		switch level {
		case "DEBUG":
			color = "36;1"
		case "INFO":
			color = "32;1"
		case "WARN":
			color = "33;1"
		case "ERROR":
			color = "31;1"
		case "PANIC", "FATAL":
			color = "31;1"
		}
		if color != "" {
			label = "\x1b[" + color + "m" + level + "\x1b[0m"
		}
	}
	pad := " "
	if len(level) < 5 {
		pad = strings.Repeat(" ", 5-len(level)+1)
	}
	fmt.Fprintf(os.Stderr, "%s [%s]%s%s\n", ts, label, pad, msg)
}
func logDebugf(format string, args ...any) {
	if debugEnabled {
		logMsg("DEBUG", fmt.Sprintf(format, args...))
	}
}
func logInfof(format string, args ...any) { logMsg("INFO", fmt.Sprintf(format, args...)) }
func logWarnf(format string, args ...any) { logMsg("WARN", fmt.Sprintf(format, args...)) }
func logErrorf(format string, args ...any) { logMsg("ERROR", fmt.Sprintf(format, args...)) }
func logDebugMsg(msg string) {
	if debugEnabled {
		logMsg("DEBUG", msg)
	}
}
EOF
