package main

import "fmt"

// ExitOutcome is returned by handlers after the pre-execution stage.
// SuccessNil determines DEBUG "Exit code 0 (SUCCESS)" suffix.
type ExitOutcome struct {
	Code       int
	Err        error
	SuccessNil bool // true => handler returned nil error
	Logged     bool // Err already logged by handler
	PreExec    bool // no debug exit line
}

func outcomeErr(code int, err error) ExitOutcome {
	return ExitOutcome{Code: code, Err: err}
}
func outcomeCode(code int) ExitOutcome {
	// non-nil style exit value (plain debug line)
	return ExitOutcome{Code: code, Err: fmt.Errorf("")}
}
func outcomeSuccess() ExitOutcome { return ExitOutcome{Code: 0, SuccessNil: true} }

type codedError struct {
	code int
	msg  string
}

func (e *codedError) Error() string { return e.msg }

func newCodedError(code int, format string, args ...any) *codedError {
	return &codedError{code: code, msg: fmt.Sprintf(format, args...)}
}
func errorCode(err error, fallback int) int {
	if ce, ok := err.(*codedError); ok {
		return ce.code
	}
	return fallback
}

// panicError indicates a simulated uncaught panic with specific message.
type panicError struct{ msg string }

func (e *panicError) Error() string { return e.msg }
