	Sections   []string // in order of first appearance, includes "" if present (or always?)
	Values     map[string]map[string]FileValue
	Deprecated []string // first-appearance unique deprecated option names
}

func newOptionFile(path string) *OptionFile {
	return &OptionFile{Path: path, Values: map[string]map[string]FileValue{}}
}

func (of *OptionFile) ensureSection(sec string) {
	if _, ok := of.Values[sec]; !ok {
		of.Values[sec] = map[string]FileValue{}
		of.Sections = append(of.Sections, sec)
	}
