func (of *OptionFile) HasSection(sec string) bool {
	_, ok := of.Values[sec]
	return ok
}

// HasOptionAnySection checks if option appears in any section (including "")
func (of *OptionFile) HasOptionAnySection(name string) bool {
	if of == nil {
		return false
	}
	for _, sec := range of.Sections {
		if _, ok := of.Values[sec][name]; ok {
			return true
		}
	}
	return false
}
func (of *OptionFile) HasOption(sec, name string) bool {
