// processValueText strips # comments outside quotes and validates quote termination.
// Returns trimmed remaining text (quotes retained).
func processValueText(raw string) (string, error) {
	var quote byte
	escaped := false
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if quote != 0 {
			if escaped {
				escaped = false
				continue
			}
			if c == '\\' {
				escaped = true
				continue
			}
			if c == quote {
				quote = 0
			}
			continue
		}
		if c == '#' {
			raw = raw[:i]
			break
		}
		if c == '\'' || c == '"' {
			quote = c
		}
	}
	if quote != 0 {
		return "", fmt.Errorf("Quoted value has no terminating quote")
	}
	return strings.TrimSpace(raw), nil
}

func parseOptionFile(path string, contents string, looseUnknown bool) (*OptionFile, error) {
	of := newOptionFile(path)
	of.ensureSection("")
	section := ""
	// Track whether "" was truly present vs implicit; writer handles section "" at front if it has values or was explicitly headed.
	// We keep Sections including "" first always; writer will skip empty "" unless it's the only.
	explicitEmptySection := false
	_ = explicitEmptySection
	seenDeprecated := map[string]bool{}
	scanner := bufio.NewScanner(strings.NewReader(contents))
	// Increase buffer for long lines (default scanner in orig may error, but be liberal)
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 16*1024*1024)
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		rawLine := scanner.Text()
		line := strings.TrimSpace(rawLine)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			end := strings.Index(line, "]")
			if end < 0 {
				return nil, newCodedError(78, "Parse error in %s line %d: unterminated section name", path, lineNo)
			}
			secName := line[1:end]
			rest := strings.TrimSpace(line[end+1:])
			// Comments after section? Treat # or ; rest as comment if starting with them
			if rest != "" && !strings.HasPrefix(rest, "#") && !strings.HasPrefix(rest, ";") {
				return nil, newCodedError(78, "Parse error in %s line %d: extra characters after section name", path, lineNo)
			}
			section = secName
			of.ensureSection(section)
			if section == "" {
				explicitEmptySection = true
			}
			continue
		}
		// Option line
		eq := strings.Index(line, "=")
		var keyPart, valPart string
		hasEq := eq >= 0
		if hasEq {
			keyPart = line[:eq]
			valPart = line[eq+1:]
		} else {
			keyPart = line
		}
		keyTrim := strings.TrimSpace(keyPart)
		canonical := canonicalOptName(keyTrim)
		loose := false
		negated := false
		name := canonical
		if strings.HasPrefix(name, "loose-") {
			loose = true
			name = name[len("loose-"):]
		}
		if strings.HasPrefix(name, "skip-") {
			negated = true
			name = name[len("skip-"):]
		} else if strings.HasPrefix(name, "disable-") {
			negated = true
			name = name[len("disable-"):]
		}
		def, known := allOptDefs[name]
		if !known {
			if loose || looseUnknown {
				continue
			}
			return nil, newCodedError(78, "%s line %d: Unknown option %q", path, lineNo, name)
		}
		// record deprecated (by name as given canonical before skip/loose stripping? Original reports base name)
		// For alias, name remains alias name
		if def.Deprecated != "" && !seenDeprecated[name] {
			seenDeprecated[name] = true
			of.Deprecated = append(of.Deprecated, name)
		}
		_ = def
		var fv FileValue
		if !hasEq {
			if def.Kind == OptBool {
				if negated {
					fv.Stored = ""
				} else {
					fv.Stored = "1"
				}
			} else if def.Kind == OptOptionalString {
				if negated {
					fv.Stored = ""
				} else {
					fv.Missing = true
					fv.Stored = ""
				}
			} else {
				return nil, newCodedError(78, "%s line %d: Missing required value for option %s", path, lineNo, name)
			}
		} else {
			v, err := processValueText(valPart)
			if err != nil {
				return nil, newCodedError(78, "Parse error in %s line %d: %s", path, lineNo, err.Error())
			}
			if negated {
				fv.Stored = boolCanonical(!parseBoolString(v))
			} else if def.Kind == OptBool {
				fv.Stored = boolCanonical(parseBoolString(v))
			} else {
				if v == "''" {
					v = ""
				}
				fv.Stored = v
			}
		}
		of.ensureSection(section)
		of.Values[section][name] = fv
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return of, nil
}

func loadOptionFile(path string, looseUnknown bool) (*OptionFile, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return parseOptionFile(path, string(data), looseUnknown)
}

func (of *OptionFile) warnDeprecated() {
	if of == nil {
		return
	}
	for _, name := range of.Deprecated {
		def := allOptDefs[name]
		if def != nil && def.Deprecated != "" {
			logWarnf("%s: Option %s is deprecated. %s", of.Path, name, def.Deprecated)
		}
	}
}

// ValueForEnv returns FileValue for env (section overrides sectionless), and whether present.
func (of *OptionFile) ValueForEnv(env, name string) (FileValue, bool) {
	if of == nil {
		return FileValue{}, false
	}
	var fv FileValue
	found := false
	if m, ok := of.Values[""]; ok {
		if v, ok2 := m[name]; ok2 {
			fv, found = v, true
		}
	}
	if env != "" {
		if m, ok := of.Values[env]; ok {
			if v, ok2 := m[name]; ok2 {
				fv, found = v, true
			}
		}
	}
	return fv, found
}

// configValueFromStored converts stored file value to Config Get value.
func configValueFromStored(fv FileValue) string {
	if fv.Missing {
		return ""
	}
	v := fv.Stored
	if len(v) >= 2 && (v[0] == '\'' || v[0] == '"') && v[len(v)-1] == v[0] {
		q := v[0]
		inner := v[1 : len(v)-1]
		// unescape \x -> x
		var b strings.Builder
		for i := 0; i < len(inner); i++ {
			if inner[i] == '\\' && i+1 < len(inner) {
				b.WriteByte(inner[i+1])
				i++
			} else {
				b.WriteByte(inner[i])
			}
		}
		inner = b.String()
		if q == '\'' {
			return inner
		}
		v = inner
	}
	if strings.HasPrefix(v, "$") && len(v) > 1 {
		return os.Getenv(v[1:])
	}
	return v
}

// Write serializes OptionFile in the format observed from add-environment.
func (of *OptionFile) Write() string {
	var b strings.Builder
	first := true
	writeSection := func(sec string) {
		m := of.Values[sec]
		if !first {
			b.WriteString("\n")
		}
		first = false
		if sec != "" {
			b.WriteString("[" + sec + "]\n")
		}
		names := make([]string, 0, len(m))
		for n := range m {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			fv := m[n]
			def := allOptDefs[n]
			if fv.Missing {
				b.WriteString(n + "\n")
			} else if fv.Stored == "" {
				b.WriteString("skip-" + n + "\n")
			} else if def != nil && def.Kind == OptBool && fv.Stored == "1" {
				b.WriteString(n + "\n")
			} else {
				b.WriteString(n + "=" + fv.Stored + "\n")
			}
		}
	}
	// Sectionless first if it has any values, then other sections in original order.
	if m, ok := of.Values[""]; ok && len(m) > 0 {
		writeSection("")
	}
	for _, sec := range of.Sections {
		if sec == "" {
			continue
		}
		writeSection(sec)
	}
	// If nothing written (completely empty), return empty
	return b.String()
}

func (of *OptionFile) Set(sec, name, stored string) {
	of.ensureSection(sec)
	of.Values[sec][name] = FileValue{Stored: stored}
}

func sameFilePath(a, b string) bool {
	ca, err1 := filepath.Abs(a)
	cb, err2 := filepath.Abs(b)
	if err1 == nil && err2 == nil {
		return ca == cb
	}
	return a == b
}
