cat > config.go <<'EOF'
package main

import (
	"os"
	"regexp"
	"strings"
)

type SourceKind int

const (
	SourceDefault SourceKind = iota
	SourceMyCnf
	SourceGlobalFile
	SourceDirFile
	SourceCLI
)

type Setting struct {
	Value   string // stored (for file: stored; for CLI: value)
	Missing bool
	Source  string // "command line" or file path
	Kind    SourceKind
}

type configLayer struct {
	settings map[string]Setting
}

type Config struct {
	layers []*configLayer // low -> high, excluding CLI
	cli    map[string]Setting
	// cliOrder records option name order of first appearance on CLI for deprec warnings
	cliOrder []string
}

func newConfig() *Config {
	return &Config{cli: map[string]Setting{}}
}

func (c *Config) clone() *Config {
	nc := &Config{cli: c.cli, cliOrder: c.cliOrder}
	nc.layers = append(nc.layers, c.layers...)
	return nc
}

func (c *Config) addLayerFromOptionFile(of *OptionFile, env string, kind SourceKind) {
	if of == nil {
		return
	}
	layer := &configLayer{settings: map[string]Setting{}}
	// sectionless then [env]
	apply := func(sec string) {
		m, ok := of.Values[sec]
		if !ok {
			return
		}
		for name, fv := range m {
			layer.settings[name] = Setting{Value: fv.Stored, Missing: fv.Missing, Source: of.Path, Kind: kind}
		}
	}
	apply("")
	if env != "" {
		apply(env)
	}
	c.layers = append(c.layers, layer)
}

// Special for .my.cnf: apply sections "", "client", "mysql" restricted, then "skeema" full.
// We implement as layers in that order.
func (c *Config) addLayerFromMyCnf(of *OptionFile) {
	if of == nil {
		return
	}
	clientOpts := map[string]bool{
		"user": true, "password": true, "host": true, "port": true, "socket": true,
		"ssl-mode": true, "connect-options": true, "schema": true, "database": true,
	}
	for _, sec := range []string{"", "client", "mysql"} {
		m, ok := of.Values[sec]
		if !ok {
			continue
		}
		layer := &configLayer{settings: map[string]Setting{}}
		for name, fv := range m {
			if !clientOpts[name] {
				continue
			}
			layer.settings[name] = Setting{Value: fv.Stored, Missing: fv.Missing, Source: of.Path, Kind: SourceMyCnf}
		}
		if len(layer.settings) > 0 {
			c.layers = append(c.layers, layer)
		}
	}
	// skeema section full
	if m, ok := of.Values["skeema"]; ok {
		layer := &configLayer{settings: map[string]Setting{}}
		for name, fv := range m {
			layer.settings[name] = Setting{Value: fv.Stored, Missing: fv.Missing, Source: of.Path, Kind: SourceMyCnf}
		}
		if len(layer.settings) > 0 {
			c.layers = append(c.layers, layer)
		}
	}
}

func (c *Config) setCLI(name, value string, missing bool) {
	if _, seen := c.cli[name]; !seen {
		// first-appearance order: only append if not already in order list
		found := false
		for _, n := range c.cliOrder {
			if n == name {
				found = true
				break
			}
		}
		if !found {
			c.cliOrder = append(c.cliOrder, name)
		}
	}
	c.cli[name] = Setting{Value: value, Missing: missing, Source: "command line", Kind: SourceCLI}
}

func (c *Config) winningSetting(name string) (Setting, bool) {
	if s, ok := c.cli[name]; ok {
		return s, true
	}
	for i := len(c.layers) - 1; i >= 0; i-- {
		if s, ok := c.layers[i].settings[name]; ok {
			return s, true
		}
	}
	return Setting{}, false
}

func (c *Config) Changed(name string) bool {
	_, ok := c.winningSetting(name)
	return ok
}
func (c *Config) OnCLI(name string) bool {
	_, ok := c.cli[name]
	return ok
}

// Get returns processed value
func (c *Config) Get(name string) string {
	// alias handling for concurrent-instances via separate helper; Get itself direct
	s, ok := c.winningSetting(name)
	if !ok {
		def := allOptDefs[name]
		if def == nil {
			return ""
		}
		if name == "password" {
			// default "$MYSQL_PWD"
			return os.Getenv("MYSQL_PWD")
		}
		return def.Default
	}
	if s.Missing {
		return ""
	}
	if s.Kind == SourceCLI || s.Kind == SourceDefault {
		return s.Value
	}
	// file sources: unquote/env-expand
	return configValueFromStored(FileValue{Stored: s.Value, Missing: s.Missing})
}

func (c *Config) GetBool(name string) bool {
	return parseBoolString(c.Get(name))
}

// GetRawStored returns winning stored value without processing (for version=="1" checks etc.)
// For bool options, stored from CLI/file has been normalized to "1"/"" in most paths,
// but CLI bool with =true stores raw "true" in our CLI parser? We normalize CLI bools there.
func (c *Config) GetEnum(name string, valid []string) (string, error) {
	v := strings.TrimSpace(c.Get(name))
	lv := strings.ToLower(v)
	for _, cand := range valid {
		if lv == cand {
			return cand, nil
		}
	}
	// Build message like original: Option <name> can only be set to one of these values: "a", "b"
	parts := make([]string, len(valid))
	for i, cand := range valid {
		parts[i] = "\"" + cand + "\""
	}
	return "", newCodedError(78, "Option %s can only be set to one of these values: %s", name, strings.Join(parts, ", "))
}

func compileIgnoreRegex(c *Config, name string) (*regexp.Regexp, error) {
	pat := c.Get(name)
	if pat == "" {
		return nil, nil
	}
	re, err := regexp.Compile(pat)
	if err != nil {
		return nil, newCodedError(78, "Invalid regexp for option %s: %s", name, pat)
	}
	return re, nil
}
EOF
gofmt -w optionfile.go config.go && echo ok"}

