// cliError is a pre-exec config error (78) already formatted without prefix handling
func cliErr(format string, args ...any) error {
	return newCodedError(78, format, args...)
}

func isOptionLike(s string) bool {
	return strings.HasPrefix(s, "-")
}

// normalizeLongName strips loose-/skip-/disable-, returns base name, loose, negated
func normalizeLongName(raw string) (name string, loose, negated bool) {
	name = canonicalOptName(raw)
	if strings.HasPrefix(name, "loose-") {
		loose = true
		name = name[len("loose-"):]
	}
	if strings.HasPrefix(name, "skip-") {
		negated = true
		name = name[len("skip-"):]
	} else if strings.HasPrefix(name, "disable-") {
		negated = true
		name = name[len("disable-"):]
	}
	return
}

func parseCLI(argv []string) (*ParsedCLI, error) {
	cfg := newConfig()
	p := &ParsedCLI{Cfg: cfg}
	seenDashDash := false
	i := 0
	for i < len(argv) {
		tok := argv[i]
		i++
		if !seenDashDash && tok == "--" {
			seenDashDash = true
			continue
		}
		if !seenDashDash && strings.HasPrefix(tok, "--") {
			// long option
			body := tok[2:]
			namePart := body
			var eqVal *string
			if eq := strings.Index(body, "="); eq >= 0 {
				namePart = body[:eq]
				v := body[eq+1:]
				eqVal = &v
			}
			name, loose, negated := normalizeLongName(namePart)
			known := knownLongOptions(p.Command)
			def, isDef := allOptDefs[name]
			if !isDef || !known[name] {
				if loose {
					continue
				}
				return nil, cliErr("CLI: Unknown option %q", name)
			}
			// set value
			if negated {
				if eqVal != nil {
					cfg.setCLI(name, boolCanonical(!parseBoolString(*eqVal)), false)
				} else {
					cfg.setCLI(name, "", false)
				}
				continue
			}
			switch def.Kind {
			case OptBool:
				if eqVal != nil {
					// Store raw trimmed? Normalize to canonical for bool checks, except version special:
					// version needs to distinguish "1" from other truthy values, so keep trimmed raw for version.
					if name == "version" {
						cfg.setCLI(name, strings.TrimSpace(*eqVal), false)
					} else {
						cfg.setCLI(name, boolCanonical(parseBoolString(*eqVal)), false)
					}
				} else {
					cfg.setCLI(name, "1", false)
				}
			case OptString:
				var v string
				if eqVal != nil {
					v = *eqVal
				} else {
					if i >= len(argv) || isOptionLike(argv[i]) {
						return nil, cliErr("CLI: Missing required value for option %s", name)
					}
					v = argv[i]
					i++
				}
				cfg.setCLI(name, v, false)
			case OptOptionalString:
				if eqVal != nil {
					cfg.setCLI(name, *eqVal, false)
				} else {
					cfg.setCLI(name, "", true)
				}
			}
			continue
		}
		if !seenDashDash && len(tok) > 1 && tok[0] == '-' && tok != "-" {
			// short option(s) - iterate bytes/runes
			chars := []rune(tok[1:])
			pos := 0
			for pos < len(chars) {
				ch := chars[pos]
				shorts := shortOptions(p.Command)
				name, ok := shorts[ch]
				if !ok {
					return nil, cliErr("CLI: Unknown option %q", string(ch))
				}
				def := allOptDefs[name]
				pos++
				rest := string(chars[pos:])
				switch def.Kind {
				case OptBool:
					cfg.setCLI(name, "1", false)
					// continue to next char
					continue
				case OptString:
					var v string
					if rest != "" {
						v = rest
						if strings.HasPrefix(v, "=") {
							v = v[1:]
						}
						pos = len(chars)
					} else {
						if i >= len(argv) || isOptionLike(argv[i]) {
							return nil, cliErr("CLI: Missing required value for option %s", name)
						}
						v = argv[i]
						i++
					}
					cfg.setCLI(name, v, false)
				case OptOptionalString:
					if rest != "" {
						// For -? and -p, rest is literal value (including leading '=' for -?)
						// Observed: -?=diff => value "=diff". For -p=foo, unknown; likely also literal "=foo".
						// However common usage -pfoo works. Keep literal.
						cfg.setCLI(name, rest, false)
						pos = len(chars)
					} else {
						cfg.setCLI(name, "", true)
					}
				}
				break // string/optional consumes rest
			}
			continue
		}
		// positional token
		if p.Command == "" {
			if _, ok := commandDefs[tok]; !ok {
				return nil, cliErr("Unknown command %q", tok)
			}
			p.Command = tok
			continue
		}
		// Special help/version tokens when no actual args collected yet
		if len(p.Args) == 0 && (tok == "help" || tok == "version") {
			if tok == "help" {
				cfg.setCLI("help", "", true)
			} else {
				cfg.setCLI("version", "1", false)
			}
			continue
		}
		def := commandDefs[p.Command]
		if len(p.Args) >= def.MaxArgs {
			return nil, cliErr("Extra command-line arg %q supplied; command %s takes a max of %d args", tok, p.Command, def.MaxArgs)
		}
		p.Args = append(p.Args, tok)
	}
	// too-few check (bypass if help changed)
	if p.Command != "" {
		def := commandDefs[p.Command]
		if len(p.Args) < def.MinArgs {
			if !cfg.Changed("help") {
				return nil, cliErr("Too few positional args supplied on command line; command %s requires at least %d args", p.Command, def.MinArgs)
			}
		}
	}
	return p, nil
}

func (p *ParsedCLI) environmentArg() (string, bool) {
	// Commands with optional env arg: diff, format, init, lint, pull, push -> default production
	// add-environment arg is the new env name (not "environment" for global config selection? handled by caller)
	switch p.Command {
	case "diff", "format", "init", "lint", "pull", "push":
		if len(p.Args) > 0 {
			return strings.TrimSpace(p.Args[0]), true
		}
		return "production", true
	}
	return "", false
}

