// tokenize statement for classification: remove comments, produce tokens where
// word tokens = letters/digits/_/$ runs, quoted tokens keep quotes, punctuation single-char.
type sqlToken struct {
	raw     string // original segment
	norm    string // uppercased word for keywords, or raw for others
	quoted  byte   // 0 if not, else quote char
	unquoted string
}

func tokenizeSQL(text string) []sqlToken {
	var toks []sqlToken
	i := 0
	for i < len(text) {
		c := text[i]
		if isSpaceByte(c) {
			i++
			continue
		}
		if c == '#' {
			for i < len(text) && text[i] != '\n' {
				i++
			}
			continue
		}
		if c == '-' && i+1 < len(text) && text[i+1] == '-' {
			third := byte(0)
			if i+2 < len(text) {
				third = text[i+2]
			}
			if i+2 >= len(text) || third == ' ' || third == '\t' || third == '\r' || third == '\n' || third < 0x20 {
				for i < len(text) && text[i] != '\n' {
					i++
				}
				continue
			}
		}
		if c == '/' && i+1 < len(text) && text[i+1] == '*' {
			i += 2
			for i+1 < len(text) && !(text[i] == '*' && text[i+1] == '/') {
				i++
			}
			if i+1 < len(text) {
				i += 2
			}
			continue
		}
		if c == '\'' || c == '"' || c == '`' {
			q := c
			start := i
			i++
			var ub strings.Builder
			for i < len(text) {
				ch := text[i]
				if ch == '\\' && q != '`' && i+1 < len(text) {
					ub.WriteByte(text[i+1])
					i += 2
					continue
				}
				if ch == q {
					if i+1 < len(text) && text[i+1] == q {
						ub.WriteByte(q)
						i += 2
						continue
					}
					i++
					break
				}
				ub.WriteByte(ch)
				i++
			}
			toks = append(toks, sqlToken{raw: text[start:i], norm: text[start:i], quoted: q, unquoted: ub.String()})
			continue
		}
		// word / number / identifier start
		r, _ := utf8.DecodeRuneInString(text[i:])
		if r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) {
			start := i
			for i < len(text) {
				r2, size := utf8.DecodeRuneInString(text[i:])
				if r2 == '_' || r2 == '$' || unicode.IsLetter(r2) || unicode.IsDigit(r2) {
					i += size
				} else {
					break
				}
			}
			raw := text[start:i]
			toks = append(toks, sqlToken{raw: raw, norm: strings.ToUpper(raw), unquoted: raw})
			continue
		}
		// single-char punctuation (by rune)
		_, size := utf8.DecodeRuneInString(text[i:])
		raw := text[i : i+size]
		toks = append(toks, sqlToken{raw: raw, norm: raw, unquoted: raw})
		i += size
	}
	return toks
}

// classifyStatement adds panicEOF field via wrapper type embedding hack: we use a field on Statement.
func classifyStatement(text string) *Statement {
	toks := tokenizeSQL(text)
	if len(toks) == 0 {
		return nil
	}
	st := &Statement{Type: StmtUnsupported}
	first := toks[0]
	if first.quoted != 0 {
		return st
	}
	switch first.norm {
	case "USE":
		if len(toks) < 2 {
			return st
		}
		// schema name = next token unquoted only if backtick; else raw as-is for other quotes?
		// Based on observed distinctness for quoted strings, preserve raw for '...' and "..."
		tok := toks[1]
		var name string
		if tok.quoted == '`' {
			name = tok.unquoted
		} else {
			name = tok.raw
		}
		// qualified use a.b : observed creates target; choose first part? Preserve whole first token.
		st.Type = StmtUse
		st.UseSchema = name
		return st
	case "CREATE":
		return classifyCreate(st, toks)
	default:
		return st
	}
}

func classifyCreate(st *Statement, toks []sqlToken) *Statement {
	idx := 1
	// Optional OR REPLACE
	if idx < len(toks) && toks[idx].norm == "OR" {
		if idx+1 < len(toks) && toks[idx+1].norm == "REPLACE" {
			idx += 2
		}
	}
	// Optional DEFINER ... (skip until object type keyword)
	if idx < len(toks) && toks[idx].norm == "DEFINER" {
		// Need at least something after DEFINER [ = ] value
		// Value may be CURRENT_USER [()] or user@host with quoted parts.
		idx++
		if idx < len(toks) && toks[idx].raw == "=" {
			idx++
		}
		if idx >= len(toks) {
			return st
		}
		// If next token is TABLE/PROCEDURE/FUNCTION immediately, definer had no value -> unsupported (observed DEFINER= TABLE)
		if isObjectTypeTok(toks[idx]) {
			return st
		}
		// Consume definer value: sequence up to object-type keyword.
		// CURRENT_USER may include ()
		if toks[idx].norm == "CURRENT_USER" {
			idx++
			if idx+1 < len(toks) && toks[idx].raw == "(" && toks[idx+1].raw == ")" {
				idx += 2
			}
		} else {
			// consume tokens until object type; definer user@host consists of token [@ token]
			// consume first token
			idx++
			if idx < len(toks) && toks[idx].raw == "@" {
				idx++
				if idx < len(toks) {
					idx++
				}
			}
		}
	}
	if idx >= len(toks) {
		return st
	}
	objTok := toks[idx]
	if objTok.quoted != 0 {
		return st
	}
	var typ StmtType
	switch objTok.norm {
	case "TABLE":
		typ = StmtCreateTable
	case "PROCEDURE":
		typ = StmtCreateProc
	case "FUNCTION":
		typ = StmtCreateFunc
	default:
		return st
	}
	idx++
	// Optional IF NOT EXISTS (also observed IF EXISTS / IF NOT treated: extractor appears to skip tokens IF NOT EXISTS loosely)
	// Logic observed: "IF EXISTS t" and "IF NOT t" both became objects named t (not EXISTS/NOT).
	if idx < len(toks) && toks[idx].norm == "IF" {
		idx++
		if idx < len(toks) && toks[idx].norm == "NOT" {
			idx++
		}
		if idx < len(toks) && toks[idx].norm == "EXISTS" {
			idx++
		}
	}
	// Object name: [schema .] name
	if idx >= len(toks) {
		return st
	}
	name1, ok := objectNameFromToken(toks[idx])
	if !ok {
		return st
	}
	idx++
	schema := ""
	name := name1
	if idx < len(toks) && toks[idx].raw == "." {
		// qualified
		if idx+1 >= len(toks) {
			return st
		}
		name2, ok2 := objectNameFromToken(toks[idx+1])
		if !ok2 {
			return st
		}
		schema = name1
		name = name2
		idx += 2
	}
	st.Type = typ
	st.ObjectName = name
	st.SchemaName = schema
	if typ == StmtCreateTable {
		if idx >= len(toks) {
			st.panicEOF = true
			return st
		}
		// CREATE TABLE ... AS SELECT / SELECT is unsupported: check remaining tokens for
		// a top-level "SELECT" or sequence AS SELECT. Simplification: if any remaining token is SELECT keyword
		// and statement doesn't start remainder with "(" or "LIKE", it's CTAS.
		// Observed: t (i int) AS SELECT also unsupported, t LIKE o supported.
		// We'll scan remaining top-level tokens (outside parens) for SELECT.
		depth := 0
		for j := idx; j < len(toks); j++ {
			t := toks[j]
			if t.raw == "(" {
				depth++
			} else if t.raw == ")" && depth > 0 {
				depth--
			} else if depth == 0 && t.quoted == 0 && t.norm == "SELECT" {
				st.Type = StmtUnsupported
				st.ObjectName = ""
				st.SchemaName = ""
				return st
			}
		}
	}
	return st
}

func isObjectTypeTok(t sqlToken) bool {
	return t.quoted == 0 && (t.norm == "TABLE" || t.norm == "PROCEDURE" || t.norm == "FUNCTION")
}

func objectNameFromToken(t sqlToken) (string, bool) {
	if t.quoted == '`' || t.quoted == '"' {
		if t.unquoted == "" {
			return "", false
		}
		return t.unquoted, true
	}
	if t.quoted != 0 {
		return "", false
	}
	// unquoted identifier: must not be purely numeric
	raw := t.raw
	if raw == "" || raw == "." {
		return "", false
	}
	allDigit := true
	for _, r := range raw {
		if !unicode.IsDigit(r) {
			allDigit = false
			break
		}
	}
	if allDigit {
		return "", false
	}
	// must start with letter/_/$ (tokenizer would split others)
	r, _ := utf8.DecodeRuneInString(raw)
	if !(unicode.IsLetter(r) || r == '_' || r == '$') {
		return "", false
	}
	return raw, true
}
