	// Helper to check delimiter at current pos
	atDelimiter := func() bool {
		if delimiter == "" {
			return false
		}
		return strings.HasPrefix(contents[pos:], delimiter)
	}
	consumeDelimiter := func() {
		for range delimiter {
			advance()
		}
	}
	// skip whitespace and comments; return error for unterminated block comment.
	// Also handles DELIMITER directives when at statement boundary.
	type scanState struct{}
	_ = scanState{}

	// processCommentOrString etc handled in main statement scanning loop.
	for pos < len(contents) {
		// At statement boundary: skip whitespace/comments, handle DELIMITER directive.
		// Loop skipping.
		for pos < len(contents) {
			// whitespace
			c := contents[pos]
			if isSpaceByte(c) {
				advance()
				continue
			}
			// line comments: # always; -- only if followed by space/control/EOL
			if c == '#' {
				// consume to end of line
				for pos < len(contents) && contents[pos] != '\n' {
					advance()
				}
				continue
			}
			if c == '-' && peekRune(1) == '-' {
				third := byte(0)
				if pos+2 < len(contents) {
					third = contents[pos+2]
				}
				if pos+2 >= len(contents) || third == ' ' || third == '\t' || third == '\r' || third == '\n' || third < 0x20 {
					for pos < len(contents) && contents[pos] != '\n' {
						advance()
					}
					continue
				}
				break
			}
			if c == '/' && peekRune(1) == '*' {
				startLine := line
				advance()
				advance()
				closed := false
				for pos < len(contents) {
					if contents[pos] == '*' && pos+1 < len(contents) && contents[pos+1] == '/' {
						advance()
						advance()
						closed = true
						break
					}
					advance()
				}
				if !closed {
					return nil, fmt.Errorf("File %s: Comment starting with /* is never closed at line %d", path, startLine)
				}
				continue
			}
			// DELIMITER directive? Case-insensitive word DELIMITER at boundary, followed by whitespace or EOL.
			rest := contents[pos:]
			if len(rest) >= 9 && strings.EqualFold(rest[:9], "delimiter") {
				after := byte(0)
				if len(rest) > 9 {
					after = rest[9]
				}
				if len(rest) == 9 || after == ' ' || after == '\t' || after == '\r' || after == '\n' {
					// consume "delimiter"
					for n := 0; n < 9; n++ {
						advance()
					}
					// delimiter value = rest of line trimmed
					start := pos
					for pos < len(contents) && contents[pos] != '\n' {
						advance()
					}
					newDelim := strings.TrimSpace(contents[start:pos])
					// If newDelim empty, original keeps? Observed subsequent stmt ended at EOF only - can keep newDelim
					// MySQL client with no arg maybe keeps old; but our observation yielded one stmt either way.
					if newDelim != "" {
