					} else {
						// no arg: leave delimiter as-is? test showed SELECT ended by ; or EOF; ambiguous.
						// Keep existing delimiter.
					}
					continue
				}
			}
			break
		}
		if pos >= len(contents) {
			break
		}
		// If at delimiter (empty statement), consume and continue
		if atDelimiter() {
			consumeDelimiter()
			continue
		}
		// Start of a real statement
		stmtLine, stmtCol := line, col
		stmtStart := pos
		// Scan until delimiter at top level, handling strings/comments.
		var stringErr error
		foundDelim := false
		for pos < len(contents) {
			if atDelimiter() {
				foundDelim = true
				break
			}
			c := contents[pos]
			// strings / quoted identifiers
			if c == '\'' || c == '"' || c == '`' {
				q := c
				qline, qcol := line, col
				advance()
				closed := false
				for pos < len(contents) {
					ch := contents[pos]
					if ch == '\\' && q != '`' {
						advance()
						if pos < len(contents) {
							advance()
						}
						continue
					}
					if ch == q {
						// doubled quote escape
						if pos+1 < len(contents) && contents[pos+1] == q {
							advance()
							advance()
							continue
						}
						advance()
						closed = true
						break
					}
					advance()
				}
