					// Message uses "String" even for backticks; column = opening quote
					stringErr = fmt.Errorf("File %s: String is missing closing quote at line %d, column %d", path, qline, qcol)
					break
				}
				continue
			}
			// comments inside statement
			if c == '#' {
				for pos < len(contents) && contents[pos] != '\n' {
					advance()
				}
				continue
			}
			if c == '-' && pos+1 < len(contents) && contents[pos+1] == '-' {
				third := byte(0)
				if pos+2 < len(contents) {
					third = contents[pos+2]
				}
				if pos+2 >= len(contents) || third == ' ' || third == '\t' || third == '\r' || third == '\n' || third < 0x20 {
					for pos < len(contents) && contents[pos] != '\n' {
						advance()
					}
					continue
				}
			}
			if c == '/' && pos+1 < len(contents) && contents[pos+1] == '*' {
				startLine := line
				advance()
				advance()
				closed := false
				for pos < len(contents) {
					if contents[pos] == '*' && pos+1 < len(contents) && contents[pos+1] == '/' {
						advance()
						advance()
						closed = true
						break
					}
					advance()
				}
				if !closed {
					return nil, fmt.Errorf("File %s: Comment starting with /* is never closed at line %d", path, startLine)
				}
				continue
			}
			advance()
		}
		if stringErr != nil {
			return nil, stringErr
		}
