			consumeDelimiter()
		}
		text := contents[stmtStart:stmtEnd]
		st := classifyStatement(text)
		if st == nil {
			continue
		}
		st.Text = text
		st.Line = stmtLine
		st.Col = stmtCol
		stmts = append(stmts, st)
