gofmt -w sqlparser.go && echo ok"}

{"command":"cat > dir.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type LogicalSchema struct {
	Name      string
	Tables    []*ObjectDef // in order
	Procs     []*ObjectDef
	Funcs     []*ObjectDef
	Creates   map[string]*ObjectDef // unused
	CharSet   string
	Collation string
}

type ObjectDef struct {
	Type string // "table", "procedure", "function"
	Name string
	Stmt *Statement
	File string
}

type Dir struct {
	Path           string // absolute
	BasePath       string // absolute base (starting dir) for rel display
	Rel            string // display for lint skipping
	Depth          int    // 0 at base
	Cfg            *Config
	OptionFile     *OptionFile
	ParentFiles    []*OptionFile // ancestor files above base, rootmost first (only for base)
	LogicalSchemas []*LogicalSchema
	Unsupported    []*Statement // statements that are unsupported (with file set via File field below)
	AllStmts       []stmtWithFile
	SubdirNames    []string // names of subdirs (non-hidden, sorted)
	Err            error    // parse error for this dir (for subdirs)
	HasSchemaCfg   bool     // schema option present in file stack (ancestors+own) for env or any? computed later
	env            string
}

type stmtWithFile struct {
	Stmt *Statement
	File string
}

func absPath(p string) string {
	abs, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return abs
}

func lintRelPath(baseAbs, dirAbs string) string {
	if baseAbs == dirAbs {
		return filepath.Base(baseAbs)
	}
	rel, err := filepath.Rel(baseAbs, dirAbs)
	if err != nil {
		return dirAbs
	}
	baseName := filepath.Base(baseAbs)
	if baseName == "/" {
		return "/" + rel
	}
	if rel == "." {
		return baseName
	}
	return baseName + "/" + filepath.ToSlash(rel)
}

// findAncestorOptionFiles returns .skeema files in ancestors of dir (excluding dir itself), rootmost first.
func findAncestorOptionFiles(absDir string) []string {
	var paths []string
	cur := filepath.Dir(absDir)
	for {
		cand := filepath.Join(cur, ".skeema")
		if _, err := os.Lstat(cand); err == nil {
			paths = append([]string{cand}, paths...)
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return paths
}

// parseDirAt parses a dir. ancestorFiles/. config inheritance.
// globalCfg is config with global layers + CLI. For base, ancestor files are loaded (and deprec-warned).
// parentCfg/Files are for subdirs: if parentDir != nil, config starts from parentCfg clone and adds own file.
func parseDir(absDir string, globalCfg *Config, env string, baseAbs string, depth int, parentCfg *Config) (*Dir, error) {
	d := &Dir{Path: absDir, BasePath: baseAbs, Depth: depth, env: env}
	d.Rel = lintRelPath(baseAbs, absDir)
	var cfg *Config
	if parentCfg != nil {
		cfg = parentCfg.clone()
	} else {
		cfg = globalCfg.clone()
		// ancestors above this dir
		for _, ancPath := range findAncestorOptionFiles(absDir) {
			of, err := loadDirOptionFile(ancPath)
			if err != nil {
				return nil, err
			}
			of.warnDeprecated()
			d.ParentFiles = append(d.ParentFiles, of)
			cfg.addLayerFromOptionFile(of, env, SourceDirFile)
		}
	}
	// own .skeema
	ownPath := filepath.Join(absDir, ".skeema")
	fi, err := os.Lstat(ownPath)
	if err != nil {
		if !os.IsNotExist(err) {
			return nil, err
		}
	} else {
		// check regular or symlink to regular
		isReg := false
		if fi.Mode().IsRegular() {
			isReg = true
		} else if fi.Mode()&os.ModeSymlink != 0 {
			if target, err2 := os.Stat(ownPath); err2 == nil && target.Mode().IsRegular() {
				isReg = true
			}
		}
		if !isReg {
			// Only error if it exists but is not regular (e.g., directory). Broken symlink also ends here.
			return nil, fmt.Errorf("%s is not a regular file, nor a symlink to a regular file", ownPath)
		}
		of, err := loadDirOptionFile(ownPath)
		if err != nil {
			return nil, err
		}
		of.warnDeprecated()
		d.OptionFile = of
		cfg.addLayerFromOptionFile(of, env, SourceDirFile)
	}
	d.Cfg = cfg

	// compile ignore regexes (validation at parse)
	ignoreTable, err := compileIgnoreRegex(cfg, "ignore-table")
	if err != nil {
		return nil, err
	}
	ignoreProc, err := compileIgnoreRegex(cfg, "ignore-proc")
	if err != nil {
		return nil, err
	}
	ignoreFunc, err := compileIgnoreRegex(cfg, "ignore-func")
	if err != nil {
		return nil, err
	}
	_ = ignoreTable

	// Read dir entries
	entries, err := os.ReadDir(absDir)
	if err != nil {
		return nil, err
	}
	// os.ReadDir returns sorted by filename.
	var sqlFiles []string
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			if strings.HasPrefix(name, ".") {
				continue
			}
			d.SubdirNames = append(d.SubdirNames, name)
			continue
		}
		// file (or symlink): only *.sql
		if strings.HasSuffix(name, ".sql") {
			full := filepath.Join(absDir, name)
			st, err := os.Stat(full)
			if err != nil {
				continue // broken symlink etc ignored
			}
			if !st.Mode().IsRegular() {
				continue
			}
			sqlFiles = append(sqlFiles, full)
		}
	}
	sort.Strings(sqlFiles)

	// Parse sql files
	var all []stmtWithFile
	for _, f := range sqlFiles {
		data, err := os.ReadFile(f)
		if err != nil {
			return nil, err
		}
		stmts, err := parseSQLFile(f, string(data))
		if err != nil {
			return nil, err
		}
		for _, s := range stmts {
			all = append(all, stmtWithFile{Stmt: s, File: f})
		}
	}
	d.AllStmts = all

	// Build logical schemas
	schemaCfgName, schemaCfgPresent := dirSchemaConfig(d, cfg, env)
	d.HasSchemaCfg = schemaCfgPresent

	type lsKey struct{ name string }
	lsMap := map[string]*LogicalSchema{}
	var lsOrder []string
	getLS := func(name string) *LogicalSchema {
		if ls, ok := lsMap[name]; ok {
			return ls
		}
		ls := &LogicalSchema{Name: name}
		lsMap[name] = ls
		lsOrder = append(lsOrder, name)
		return ls
	}
	if schemaCfgPresent {
		getLS(schemaCfgName)
	}
	// duplicates tracking per logical schema: type+name -> first stmtWithFile
	type dupKey struct {
		ls, typ, name string
	}
	seen := map[dupKey]stmtWithFile{}

	// For USE handling, state resets per file.
	currentFile := ""
	currentUse := ""
	for _, sw := range all {
		if sw.File != currentFile {
			currentFile = sw.File
			currentUse = ""
		}
		s := sw.Stmt
		switch s.Type {
		case StmtUnsupported:
			// record with file
			s2 := *s
			d.Unsupported = append(d.Unsupported, &s2)
			// store file in a parallel way: reuse Text? We'll keep AllStmts; warnings use AllStmts.
		case StmtUse:
			currentUse = s.UseSchema
		case StmtCreateTable, StmtCreateProc, StmtCreateFunc:
			typ := "table"
			var ignoreRe *regexp.Regexp
			switch s.Type {
			case StmtCreateTable:
				typ = "table"
				ignoreRe = ignoreTable
			case StmtCreateProc:
				typ = "procedure"
				ignoreRe = ignoreProc
			case StmtCreateFunc:
				typ = "function"
				ignoreRe = ignoreFunc
			}
			if ignoreRe != nil && ignoreRe.MatchString(s.ObjectName) {
				continue
			}
			var lsName string
			if schemaCfgPresent {
				lsName = schemaCfgName
			} else if s.SchemaName != "" {
				lsName = s.SchemaName
			} else {
				lsName = currentUse
			}
			ls := getLS(lsName)
			key := dupKey{ls: lsName, typ: typ, name: s.ObjectName}
			if first, dup := seen[key]; dup {
				return nil, fmt.Errorf("%s `%s` defined multiple times in same directory: %s line %d and %s line %d", typ, s.ObjectName, first.File, first.Stmt.Line, sw.File, s.Line)
			}
			seen[key] = sw
			obj := &ObjectDef{Type: typ, Name: s.ObjectName, Stmt: s, File: sw.File}
			switch typ {
			case "table":
				ls.Tables = append(ls.Tables, obj)
			case "procedure":
				ls.Procs = append(ls.Procs, obj)
			case "function":
				ls.Funcs = append(ls.Funcs, obj)
			}
		}
	}
	for _, n := range lsOrder {
		d.LogicalSchemas = append(d.LogicalSchemas, lsMap[n])
	}
	// If schemaCfgPresent but LS empty still included (getLS above).
	// If no schema config and LSes are only empty (e.g., all objects ignored), getLS only called for non-ignored objects, so fine.
	// However USE-only schemas are not created (getLS only on objects).
	return d, nil
}

func loadDirOptionFile(path string) (*OptionFile, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return parseOptionFile(path, string(data), false)
}

// dirSchemaConfig determines if schema option is defined for this dir via files (ancestor+own) for env.
// Returns name (processed config value) and present.
// Rules inferred: present if any file in stack has schema in section "" or [env]
// (even if empty). Global/my.cnf sources are excluded - but our cfg layers before dir files may have global file schema.
// Global schema would have errored earlier for dir commands except init; for safety require source kind DirFile.
func dirSchemaConfig(d *Dir, cfg *Config, env string) (string, bool) {
	// inspect layers for a DirFile setting of schema
	present := false
	for _, layer := range cfg.layers {
		if s, ok := layer.settings["schema"]; ok && s.Kind == SourceDirFile {
			present = true
		}
	}
	if !present {
		// Also CLI schema for init handled by caller, not here.
		return "", false
	}
	return cfg.Get("schema"), true
}

// hasNamedLogicalSchema: any LS with non-empty name, or schema config present (even empty name counts as target for diff)
func (d *Dir) hasTargetsForDiff() bool {
	if d.HasSchemaCfg {
		return true
	}
	for _, ls := range d.LogicalSchemas {
		if ls.Name != "" {
			return true
		}
	}
	return false
}

func (d *Dir) hasLogicalSchemas() bool {
	return len(d.LogicalSchemas) > 0
}

// unsupportedWarnings returns stmtWithFile for unsupported statements (in order)
func (d *Dir) unsupportedStmts() []stmtWithFile {
	var out []stmtWithFile
	for _, sw := range d.AllStmts {
		if sw.Stmt.Type == StmtUnsupported {
			out = append(out, sw)
		}
	}
	return out
}

// subdirs parses immediate subdirs (depth+1). If depth>=5 and there are subdirs, returns max-depth error indicator.
// Caller handles per-command logging for max depth.
var errMaxDepth = fmt.Errorf("max depth reached")

func (d *Dir) parseSubdirs(globalCfg *Config) (subs []*Dir, maxDepthErr bool) {
	if d.Depth >= 5 {
		if len(d.SubdirNames) > 0 {
			return nil, true
		}
		return nil, false
	}
	for _, name := range d.SubdirNames {
		subPath := filepath.Join(d.Path, name)
		sub, err := parseDir(subPath, globalCfg, d.env, d.BasePath, d.Depth+1, d.Cfg)
		if err != nil {
			// create placeholder dir with Err
			sd := &Dir{Path: subPath, BasePath: d.BasePath, Depth: d.Depth + 1, Err: err, env: d.env}
			sd.Rel = lintRelPath(d.BasePath, subPath)
			sd.Cfg = d.Cfg
			subs = append(subs, sd)
		} else {
			subs = append(subs, sub)
		}
	}
	return subs, false
}
