	inst := &Instance{Host: hostForDial, Port: port, PortStr: portStrForDSN, Socket: socketRaw, IsSocket: isSocket, cfg: cfg, dirPath: dirPath}
	// ssl-mode validation and DSN build may error
	dsn, err := buildDSN(cfg, inst, hostForDisplay, portStrForDSN)
	if err != nil {
		return nil, err
	}
	inst.DSN = dsn
	// DSN driver parse validation for invalid port (negative or >?)
	if !isSocket {
		if port < 0 {
			return nil, newCodedError(78, "Invalid connection information for %s (DSN=%s): invalid port %d supplied", dirPath, maskedDSN(dsn, cfg), port)
		}
		// connect-options timeout parse errors surface during DSN parse in driver before port sometimes;
		// We'll validate timeout-like params here.
		if err := validateDSNParams(cfg); err != nil {
			return nil, newCodedError(78, "Invalid connection information for %s (DSN=%s): %s", dirPath, maskedDSN(dsn, cfg), err.Error())
		}
	} else {
		if err := validateDSNParams(cfg); err != nil {
			return nil, newCodedError(78, "Invalid connection information for %s (DSN=%s): %s", dirPath, maskedDSN(dsn, cfg), err.Error())
		}
	}
	if isSocket {
		inst.Display = fmt.Sprintf("%s:%s", hostForDisplay, socketRaw)
	} else {
		inst.Display = fmt.Sprintf("%s:%s", hostForDisplay, portStrForDSN)
	}
	return inst, nil
}

func maskedDSN(dsn string, cfg *Config) string {
	// buildDSN already masked password as ***** if present
	return dsn
}

func buildDSN(cfg *Config, inst *Instance, hostForDisplay, portStr string) (string, error) {
	user := cfg.Get("user")
	pass := cfg.Get("password")
	sslRawChanged := cfg.Changed("ssl-mode")
	sslVal := strings.ToLower(strings.TrimSpace(cfg.Get("ssl-mode")))
	if !(sslVal == "" || sslVal == "disabled" || sslVal == "preferred" || sslVal == "required") {
		return "", newCodedError(78, "Invalid connection options: Option ssl-mode can only be set to one of these values: \"disabled\", \"preferred\", \"required\", \"\"")
	}
	// Parse connect-options
	extra, err := parseConnectOptions(cfg.Get("connect-options"))
	if err != nil {
		return "", newCodedError(78, "Invalid connection options: %s", err.Error())
	}
	params := map[string]string{
		"default_storage_engine": "'InnoDB'",
		"foreign_key_checks":     "0",
		"interpolateParams":      "true",
		"readTimeout":            "20s",
		"timeout":                "5s",
		"writeTimeout":           "5s",
	}
	flavor := strings.TrimSpace(cfg.Get("flavor"))
	// TLS logic
	if sslVal == "disabled" {
		params["tls"] = "false"
	} else if flavor != "" && !sslRawChanged {
		// flavor known? use preferred if flavor parses valid; for our purposes any non-empty flavor -> preferred unless bogus?
		// DSN for flavor=mysql:8.0 showed tls=preferred. Bogus flavor likely oldtls; approximate by checking known vendors.
		if isKnownFlavor(flavor) {
			params["tls"] = "preferred"
		} else {
			params["tls"] = "oldtls"
			if sslVal == "preferred" || !sslRawChanged {
				// default (unset) also had fallback with oldtls
				params["allowFallbackToPlaintext"] = "true"
			}
		}
	} else {
		params["tls"] = "oldtls"
		// fallback when ssl is preferred OR (not changed and default assumed preferred) but NOT when explicitly set to "" or required.
		if sslVal == "preferred" || !sslRawChanged {
			params["allowFallbackToPlaintext"] = "true"
		}
	}
	// If user explicitly set ssl-mode="" (Changed and empty) -> no fallback (handled)
	for k, v := range extra {
		params[k] = v
	}
	// Build DSN sorted by param key, values URL query-escaped
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var q []string
	for _, k := range keys {
		q = append(q, k+"="+url.QueryEscape(params[k]))
	}
	// auth part
	auth := user
	if pass != "" {
		auth += ":*****"
	}
	network := "tcp"
	addr := hostForDisplay + ":" + portStr
	if inst.IsSocket {
		network = "unix"
		addr = inst.Socket
	}
	dsn := fmt.Sprintf("%s@%s(%s)/?%s", auth, network, addr, strings.Join(q, "&"))
	return dsn, nil
}

func validateDSNParams(cfg *Config) error {
	extra, _ := parseConnectOptions(cfg.Get("connect-options"))
	// mysql driver parses timeout/readTimeout/writeTimeout as durations
	for _, k := range []string{"timeout", "readTimeout", "writeTimeout"} {
		if v, ok := extra[k]; ok {
			if _, err := time.ParseDuration(v); err != nil {
				return err
			}
		}
	}
	return nil
}

func isKnownFlavor(f string) bool {
	lf := strings.ToLower(strings.TrimSpace(f))
	for _, p := range []string{"mysql:", "mariadb:", "percona:"} {
		if strings.HasPrefix(lf, p) {
			// version part must start with digit
			v := lf[len(p):]
			return len(v) > 0 && v[0] >= '0' && v[0] <= '9'
		}
	}
	return false
}

// parseConnectOptions splits by commas not inside single quotes.
func parseConnectOptions(s string) (map[string]string, error) {
	out := map[string]string{}
	if strings.TrimSpace(s) == "" {
		return out, nil
	}
	// Check comma placement: invalid if comma at start, end(?) or consecutive outside quotes.
	// E.g "a=1,,b=2" offset of 2nd comma (4).
	inQuote := false
	var q byte
	prevComma := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == q {
				inQuote = false
			}
			continue
		}
		if c == '\'' || c == '"' {
			inQuote = true
			q = c
			prevComma = false
			continue
		}
		if c == ',' {
			if i == 0 || prevComma {
				return nil, fmt.Errorf("Invalid comma placement in option value at byte offset %d in connect-options \"%s\"", i, s)
			}
			prevComma = true
		} else if c != ' ' && c != '\t' {
			prevComma = false
		}
	}
	// split respecting quotes
	var parts []string
	start := 0
	inQuote = false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == q {
				inQuote = false
			}
			continue
		}
		if c == '\'' || c == '"' {
			inQuote = true
			q = c
			continue
		}
		if c == ',' {
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	parts = append(parts, s[start:])
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if eq := strings.Index(part, "="); eq >= 0 {
			k := strings.TrimSpace(part[:eq])
			v := strings.TrimSpace(part[eq+1:])
			out[k] = v
		} else {
			// bare key -> value "true"? driver DSN would treat param without = as key with empty? Observed foo alone likely goes as session var.
			// We'll set to "true" to approximate MySQL SET syntax? Keep empty.
			out[part] = ""
		}
	}
	return out, nil
}

// connect attempts a TCP/Unix dial and a minimal read of server handshake if possible.
// Returns error like driver dial errors for refused/DNS etc.
func (inst *Instance) connect() error {
	timeout := 5 * time.Second
	// Respect timeout connect-option if valid
	if extra, err := parseConnectOptions(inst.cfg.Get("connect-options")); err == nil {
		if v, ok := extra["timeout"]; ok {
			if d, err2 := time.ParseDuration(v); err2 == nil {
				timeout = d
			}
		}
	}
	var conn net.Conn
	var err error
	d := net.Dialer{Timeout: timeout}
	if inst.IsSocket {
		conn, err = d.Dial("unix", inst.Socket)
	} else {
		addr := net.JoinHostPort(strings.Trim(inst.Host, "[]"), strconv.Itoa(inst.Port))
		// But JoinHostPort revalidates port; for >65535 original error is "dial tcp: address 99999: invalid port"
		// net.Dial with our addr will produce similar if we construct host:port manually when Port out of range.
		if inst.Port > 65535 {
			// emulate
			conn, err = d.Dial("tcp", fmt.Sprintf("%s:%d", inst.Host, inst.Port))
		} else {
			conn, err = d.Dial("tcp", addr)
		}
	}
	if err != nil {
		return err
	}
	defer conn.Close()
	// Try reading MySQL handshake packet (first packet). If server is not MySQL or closes, emulate driver errors.
	// Set read deadline 20s (or readTimeout)
	readTimeout := 20 * time.Second
	if extra, err2 := parseConnectOptions(inst.cfg.Get("connect-options")); err2 == nil {
		if v, ok := extra["readTimeout"]; ok {
			if dd, e := time.ParseDuration(v); e == nil {
				readTimeout = dd
			}
		}
	}
	conn.SetDeadline(time.Now().Add(readTimeout))
	header := make([]byte, 4)
	n, err := readFull(conn, header)
	if err != nil {
		if n == 0 {
			// driver reports EOF / invalid connection depending
			// For plain TCP accept+close, go-sql-driver returns "invalid connection" maybe wrapped as driver: bad connection
			// We'll return err directly; most tests use closed ports anyway.
			return err
		}
		return err
	}
	length := int(uint32(header[0]) | uint32(header[1])<<8 | uint32(header[2])<<16)
	if length <= 0 || length > 16*1024*1024 {
		return fmt.Errorf("invalid connection")
	}
	payload := make([]byte, length)
	if _, err := readFull(conn, payload); err != nil {
		return err
	}
	if len(payload) > 0 && payload[0] == 0xff {
		// ERR packet
		return parseMySQLError(payload)
	}
	// Handshake v10 first byte protocol version (10)
	if len(payload) == 0 || payload[0] != 10 {
		return fmt.Errorf("invalid connection")
	}
	// Parse server version (null-terminated after first byte)
	rest := payload[1:]
	end := strings.IndexByte(string(rest), 0)
	if end >= 0 {
		inst.flavor = string(rest[:end])
	}
	// We have established a MySQL-like handshake. Full auth + queries are beyond scope;
	// signal with a special error that caller can treat as connected-but-unsupported.
	return &connectedButUnsupportedError{serverVersion: inst.flavor}
}

type connectedButUnsupportedError struct{ serverVersion string }

func (e *connectedButUnsupportedError) Error() string {
	// This path is not expected in tests without a real DB. Use a driver-ish phrase.
	return "invalid connection"
}

func readFull(conn net.Conn, buf []byte) (int, error) {
	total := 0
	for total < len(buf) {
		n, err := conn.Read(buf[total:])
		total += n
		if err != nil {
			return total, err
		}
	}
	return total, nil
}

func parseMySQLError(payload []byte) error {
	// ERR packet: 0xff, error code 2 bytes LE, then if next '#' sqlstate 5 bytes, then message
	if len(payload) < 3 {
		return fmt.Errorf("invalid connection")
	}
	code := int(uint16(payload[1]) | uint16(payload[2])<<8)
	msgStart := 3
	state := ""
	if len(payload) > 3 && payload[3] == '#' && len(payload) >= 9 {
		state = string(payload[4:9])
		msgStart = 9
	}
	msg := ""
	if msgStart < len(payload) {
		msg = string(payload[msgStart:])
	}
	if state != "" {
		return fmt.Errorf("Error %d (%s): %s", code, state, msg)
	}
	return fmt.Errorf("Error %d: %s", code, msg)
}

// Host wrapper handling
func applyTemplateVars(s string, vars map[string]string) (string, error) {
	var b strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '{' {
			// {{ ... }} is literal pass-through observed: {{HOST}} stayed as such (shell quoted), treat as escaped? We'll return as-is.
			if i+1 < len(s) && s[i+1] == '{' {
				b.WriteString("{{")
				i += 2
				continue
			}
			end := strings.IndexByte(s[i:], '}')
			if end < 0 {
				return "", fmt.Errorf("Variable name missing closing brace: %s", s[i:])
			}
			nameRaw := s[i+1 : i+end]
			name := strings.ToUpper(nameRaw)
			// Note: no trimming; "{HOST }" -> Unknown variable HOST (reported trimmed trailing? Observed "HOST")
			reportName := strings.TrimSpace(name)
			val, ok := vars[name]
			if !ok {
				// Original reports original case-uppercased (?) "{HOST:foo}" -> HOST:FOO, "{123}" -> 123, "{}" -> blank after space
				return "", fmt.Errorf("Unknown variable %s", reportName)
			}
			b.WriteString(shellEscape(val))
			i += end + 1
			continue
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String(), nil
}

func shellEscape(v string) string {
	if v == "" {
		return "''"
	}
	// If safe chars only, return as-is.
	safe := true
	for _, r := range v {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("_@%+=:,./-", r)) {
			safe = false
			break
		}
	}
	if safe {
		return v
	}
	return "'" + strings.ReplaceAll(v, "'", "'\"'\"'") + "'"
}

// resolveHosts returns list of host strings for a dir cfg.
func resolveHosts(cfg *Config, dirPath, schemaName, env string) ([]string, error) {
	wrapper := strings.TrimSpace(cfg.Get("host-wrapper"))
	hostVal := cfg.Get("host")
	if wrapper == "" {
		if strings.TrimSpace(hostVal) == "" {
			return nil, nil
		}
		return []string{hostVal}, nil
	}
	// host-wrapper present: only invoked if host non-empty by callers; still implement here.
	vars := map[string]string{
		"HOST":        hostVal,
		"SCHEMA":      schemaName,
		"ENVIRONMENT": env,
	}
	cmdStr, err := applyTemplateVars(wrapper, vars)
	if err != nil {
		return nil, err
	}
	cmd := exec.Command("/bin/sh", "-c", cmdStr)
	cmd.Stderr = stderrWriter{}
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	var hosts []string
	for _, line := range strings.Split(string(out), "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			hosts = append(hosts, line)
		}
	}
	return hosts, nil
}

