cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const versionString = "skeema version 1.13.2-community, commit 9a541d7, released 2026-08-10T23:10:35Z"

func main() {
	os.Exit(runMain())
}

func runMain() (exitCode int) {
	defer func() {
		if r := recover(); r != nil {
			exitCode = handlePanic(r)
		}
	}()
	parsed, err := parseCLI(os.Args[1:])
	if err != nil {
		logErrorf("%s", err.Error())
		return errorCode(err, 78)
	}
	// Global config stage (pre-exec)
	globalCfg, preErr := buildGlobalConfig(parsed)
	if preErr != nil {
		// errors from this stage are either already logged (password) or need logging
		if pe, ok := preErr.(*preExecError); ok {
			if !pe.logged {
				logErrorf("%s", pe.msg)
			}
			return pe.code
		}
		logErrorf("%s", preErr.Error())
		return errorCode(preErr, 78)
	}
	debugEnabled = globalCfg.GetBool("debug")

	outcome := dispatch(parsed, globalCfg)
	return finishOutcome(outcome)
}

type preExecError struct {
	code   int
	msg    string
	logged bool
}

func (e *preExecError) Error() string { return e.msg }

func finishOutcome(o ExitOutcome) int {
	if o.Err != nil && o.Err.Error() != "" && !o.Logged {
		// Panic errors are handled specially elsewhere
		if pe, ok := o.Err.(*panicError); ok {
			return handleSimulatedPanic(pe)
		}
		logErrorf("%s", o.Err.Error())
	}
	if pe, ok := o.Err.(*panicError); ok {
		return handleSimulatedPanic(pe)
	}
	if debugEnabled {
		if o.SuccessNil {
			logDebugf("Exit code 0 (SUCCESS)")
		} else {
			logDebugf("Exit code %d", o.Code)
		}
	}
	return o.Code
}

func handleSimulatedPanic(pe *panicError) int {
	// For the known parser panic condition
	if debugEnabled {
		// Original prints full stack at DEBUG; emit a minimal marker line to indicate.
		// Exact stack contents contain volatile pointers, not reproducible.
		logDebugf("goroutine 1 [running]:")
	}
	logErrorf("Uncaught panic in github.com/skeema/skeema/internal/tengo.(*parser).skipUntilSequence at github.com/skeema/skeema/internal/tengo/parser.go:412: %s", pe.msg)
	logErrorf("This situation indicates a bug in Skeema. Use --debug to view full stack trace.")
	logErrorf("Please file an issue report at https://github.com/skeema/skeema/issues with any available background information.")
	if debugEnabled {
		logDebugf("Exit code 2")
	}
	return 2
}

func handlePanic(r any) int {
	if pe, ok := r.(*panicError); ok {
		return handleSimulatedPanic(pe)
	}
	msg := fmt.Sprintf("%v", r)
	if debugEnabled {
		logDebugf("goroutine 1 [running]:")
	}
	// Best-effort generic panic reporting
	logErrorf("Uncaught panic: %s", msg)
	logErrorf("This situation indicates a bug in Skeema. Use --debug to view full stack trace.")
	logErrorf("Please file an issue report at https://github.com/skeema/skeema/issues with any available background information.")
	if debugEnabled {
		logDebugf("Exit code 2")
	}
	return 2
}

func buildGlobalConfig(parsed *ParsedCLI) (*Config, error) {
	cfg := parsed.Cfg // has CLI only
	envForGlobal := ""
	if env, ok := parsed.environmentArg(); ok {
		envForGlobal = env
	} else if parsed.Command == "add-environment" && len(parsed.Args) > 0 {
		envForGlobal = strings.TrimSpace(parsed.Args[0])
	}
	home, _ := os.UserHomeDir()
	// /etc/skeema (lowest)
	if _, err := os.Lstat("/etc/skeema"); err == nil {
		loadGlobalFile(cfg, "/etc/skeema", envForGlobal, false, SourceGlobalFile)
	}
	// ~/.my.cnf unless CLI disables my-cnf
	cliMyCnf := true
	if cfg.OnCLI("my-cnf") {
		cliMyCnf = cfg.GetBool("my-cnf") // CLI only stage, layers not yet checked? cfg currently no layers except maybe /etc.
		// GetBool will consider /etc layer too; but CLI wins over layers, so okay.
	}
	if cliMyCnf && home != "" {
		myCnfPath := filepath.Join(home, ".my.cnf")
		if _, err := os.Lstat(myCnfPath); err == nil {
			loadMyCnf(cfg, myCnfPath)
		}
	}
	// ~/.skeema
	if home != "" {
		p := filepath.Join(home, ".skeema")
		if _, err := os.Lstat(p); err == nil {
			loadGlobalFile(cfg, p, envForGlobal, false, SourceGlobalFile)
		}
	}
	// CLI deprecation warnings (unique in order)
	warnCLIDeprecated(cfg)
	// host/schema global restriction
	if err := checkHostSchemaGlobal(cfg, parsed.Command); err != nil {
		return nil, &preExecError{code: 78, msg: err.Error()}
	}
	// password prompt
	if s, changed := cfg.winningSetting("password"); changed && s.Missing {
		pw, err := promptPassword()
		if err != nil {
			return nil, &preExecError{code: 78, msg: "", logged: true}
		}
		cfg.setCLI("password", pw, false)
	}
	return cfg, nil
}

func loadGlobalFile(cfg *Config, path string, env string, loose bool, kind SourceKind) {
	data, err := os.ReadFile(path)
	if err != nil {
		logWarnf("Ignoring global option file %s due to read error: %s", path, err.Error())
		return
	}
	of, err := parseOptionFile(path, string(data), loose)
	if err != nil {
		logWarnf("Ignoring global option file %s due to parse error: %s", path, err.Error())
		return
	}
	of.warnDeprecated()
	cfg.addLayerFromOptionFile(of, env, kind)
}

func loadMyCnf(cfg *Config, path string) {
	data, err := os.ReadFile(path)
	if err != nil {
		logWarnf("Ignoring global option file %s due to read error: %s", path, err.Error())
		return
	}
	of, err := parseOptionFile(path, string(data), true)
	if err != nil {
		logWarnf("Ignoring global option file %s due to parse error: %s", path, err.Error())
		return
	}
	of.warnDeprecated()
	cfg.addLayerFromMyCnf(of)
}

func warnCLIDeprecated(cfg *Config) {
	seen := map[string]bool{}
	for _, name := range cfg.cliOrder {
		if seen[name] {
			continue
		}
		seen[name] = true
		def := allOptDefs[name]
		if def != nil && def.Deprecated != "" {
			logWarnf("Option --%s is deprecated. %s", name, def.Deprecated)
		}
	}
}

func checkHostSchemaGlobal(cfg *Config, cmd string) error {
	for _, name := range []string{"host", "schema"} {
		s, changed := cfg.winningSetting(name)
		if !changed {
			continue
		}
		if strings.TrimSpace(cfg.Get(name)) == "" {
			continue
		}
		if s.Kind == SourceMyCnf || s.Kind == SourceDirFile || s.Kind == SourceDefault {
			continue
		}
		if name == "host" && (cmd == "init" || cmd == "add-environment") {
			continue
		}
		if name == "schema" && cmd == "init" {
			continue
		}
		via := s.Source
		// Source for CLI is "command line"
		return fmt.Errorf("The %s option cannot be set via %s for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options", name, via)
	}
	return nil
}

func dispatch(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	cmd := parsed.Command
	helpChanged := cfg.Changed("help")
	versionVal := ""
	if s, ok := cfg.winningSetting("version"); ok {
		// winning may be file: process file bool normalized to 1/""; CLI raw trimmed.
		if s.Kind == SourceCLI {
			versionVal = strings.TrimSpace(s.Value)
		} else {
			versionVal = cfg.Get("version") // 1 or ""
			if cfg.GetBool("version") {
				versionVal = "1"
			}
		}
	}
	versionWanted := versionVal == "1"

	if helpChanged {
		var target string
		explicitVal := ""
		// help value processing: CLI missing => "", else trimmed processed value
		if s, ok := cfg.winningSetting("help"); ok && !s.Missing {
			explicitVal = strings.TrimSpace(cfg.Get("help"))
		}
		if cmd == "" {
			target = explicitVal
		} else if cmd == "help" {
			if explicitVal != "" {
				target = explicitVal
			} else {
				target = ""
			}
		} else {
			target = cmd
		}
		return doHelpTarget(target)
	}
	if cmd == "help" {
		if versionWanted {
			fmt.Println(versionString)
			return outcomeSuccess()
		}
		target := ""
		if len(parsed.Args) > 0 {
			target = strings.TrimSpace(parsed.Args[0])
		}
		return doHelpTarget(target)
	}
	if versionWanted || cmd == "version" {
		fmt.Println(versionString)
		return outcomeSuccess()
	}
	if cmd == "" {
		fmt.Print(helpTexts["root"])
		return outcomeSuccess()
	}
	// Real commands
	switch cmd {
	case "lint":
		return lintHandler(parsed, cfg)
	case "format":
		return formatHandler(parsed, cfg)
	case "diff":
		return diffPushHandler(parsed, cfg, false)
	case "push":
		return diffPushHandler(parsed, cfg, true)
	case "pull":
		return pullHandler(parsed, cfg)
	case "init":
		return initHandler(parsed, cfg)
	case "add-environment":
		return addEnvironmentHandler(parsed, cfg)
	}
	return outcomeSuccess()
}

func doHelpTarget(target string) ExitOutcome {
	target = strings.TrimSpace(target)
	if target == "" {
		fmt.Print(helpTexts["root"])
		return outcomeSuccess()
	}
	if txt, ok := helpTexts[target]; ok {
		fmt.Print(txt)
		return outcomeSuccess()
	}
	// unknown command runtime error code 2
	return outcomeErr(2, fmt.Errorf("Unknown command %q", target))
}
