package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

func promptPassword() (string, error) {
	fmt.Fprint(os.Stderr, "Enter password: ")
	if !isTTY(os.Stdin) {
		fmt.Fprintln(os.Stderr)
		logErrorf("STDIN must be a TTY to read password")
		logErrorf("Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
		return "", fmt.Errorf("STDIN must be a TTY to read password")
	}
	// Disable echo
	fd := int(os.Stdin.Fd())
	oldState, err := tcGetAttr(fd)
	if err == nil {
		newState := *oldState
		newState.Lflag &^= echoFlag
		_ = tcSetAttr(fd, &newState)
		defer tcSetAttr(fd, oldState)
	}
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	fmt.Fprintln(os.Stderr)
	if err != nil && line == "" {
		return "", err
	}
	return strings.TrimRight(line, "\r\n"), nil
}

const (
	tcgets   = 0x5401
	tcsets   = 0x5402
	echoFlag = 0x0008
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

func tcGetAttr(fd int) (*termios, error) {
	var t termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(tcgets), uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, errno
	}
	return &t, nil
}
func tcSetAttr(fd int, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(tcsets), uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}
