		}
		if _, err := cfg.GetEnum("docker-cleanup", allOptDefs["docker-cleanup"].Valid); err != nil {
			return err
		}
		if !isKnownFlavor(flavor) {
			return fmt.Errorf("no flavor supplied")
		}
		if _, err := exec.LookPath("docker"); err != nil {
			return fmt.Errorf("unable to find `docker` command-line client among directories in PATH")
