	}
	env, _ := parsed.environmentArg()
	skipped := 0
	firstOnly := cfg.GetBool("first-only")
	var processDir func(d *Dir)
	var walk func(d *Dir)
	processDir = func(d *Dir) {
		// Determine candidacy
		// Special "other environments define schema" based on own OptionFile
		noSchemaOtherEnv := false
		if !d.HasSchemaCfg && d.OptionFile != nil {
			// schema in any section other than "" and env, and not in ""/env
			hasOther := false
			for _, sec := range d.OptionFile.Sections {
				if sec == "" || sec == env {
					continue
				}
				if d.OptionFile.HasOption(sec, "schema") {
					hasOther = true
				}
			}
			if hasOther && !d.OptionFile.HasOption("", "schema") && !d.OptionFile.HasOption(env, "schema") {
