func upgradeFormatNotice(cfg *Config) {
	if !cfg.Changed("format") {
		logDebugf("Upgrade notice: the --format option, which currently defaults to true in Skeema v1, will change to default to false in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
	}
}

func codeMax(a, b int) int {
	if b > a {
		return b
	}
	return a
}

// ---------------- Lint ----------------
func lintHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	upgradeFormatNotice(cfg)
	base, err := getBaseDir(parsed, cfg)
	if err != nil {
		return baseErrorOutcome(err)
	}
	warnings := 0
	skipped := 0
	resultCode := 0
	var recurse func(d *Dir)
	recurse = func(d *Dir) {
		logInfof("Linting %s", d.Path)
		if d.hasLogicalSchemas() {
			if werr := acquireWorkspace(d); werr != nil {
				logErrorf("Skipping directory %s due to error: %s", d.Rel, werr.Error())
				if strings.Contains(werr.Error(), "unable to find `docker`") {
					logErrorf("Skeema v1.11+ no longer includes a built-in Docker client. If you are using workspace=docker while also running `skeema` itself in a container, be sure to put a Linux `docker` client CLI binary in the container as well.")
					logErrorf("For more information, see https://github.com/skeema/skeema/issues/186#issuecomment-1648483625")
				}
				skipped++
				resultCode = codeMax(resultCode, errorCode(werr, 2))
				return
			}
			// workspace "succeeded" (should not happen with our minimal client)
			return
		}
		for _, sw := range d.unsupportedStmts() {
			logWarnf("%s:%d:%d: Ignoring unsupported or unparseable SQL statement", sw.File, sw.Stmt.Line, sw.Stmt.Col)
			warnings++
		}
		if d.Depth >= 5 && len(d.SubdirNames) > 0 {
			logErrorf("Not walking subdirs of %s: max depth reached", d.Path)
			skipped++
			resultCode = codeMax(resultCode, 2)
			return
		}
		for _, name := range d.SubdirNames {
			sub, serr := parseOneSubdir(d, name, cfg)
			if serr != nil {
				rel := lintRelPath(d.BasePath, filepath.Join(d.Path, name))
				logErrorf("Skipping directory %s due to error: %s", rel, serr.Error())
				skipped++
				resultCode = codeMax(resultCode, 78)
				continue
			}
			recurse(sub)
		}
	}
	recurse(base)
	if skipped > 0 {
		word := "operation"
		if skipped != 1 {
			word = "operations"
		}
		logErrorf("Skipped %d %s due to fatal errors", skipped, word)
		if resultCode == 0 {
			resultCode = 2
		}
		return ExitOutcome{Code: resultCode, Err: fmt.Errorf(""), Logged: true}
	}
	if warnings > 0 {
		word := "warning"
		if warnings != 1 {
			word = "warnings"
		}
		logWarnf("Found %d %s", warnings, word)
		return ExitOutcome{Code: 1, Err: fmt.Errorf(""), Logged: true}
	}
	return outcomeSuccess()
}

func parseOneSubdir(parent *Dir, name string, globalCfg *Config) (*Dir, error) {
	subPath := filepath.Join(parent.Path, name)
	return parseDir(subPath, globalCfg, parent.env, parent.BasePath, parent.Depth+1, parent.Cfg)
}

// ---------------- Format ----------------
func formatHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	base, err := getBaseDir(parsed, cfg)
	if err != nil {
		// format returns non-nil style even for errors; base error logged by wrapper
		if pe, ok := err.(*panicError); ok {
			return ExitOutcome{Code: 2, Err: pe}
		}
		return outcomeErr(errorCode(err, 2), err)
	}
	write := cfg.GetBool("write")
	// Note: write may be overridden per-dir; verb based on each dir's cfg in original? Use per-dir.
	resultCode := 0
	var recurse func(d *Dir)
	recurse = func(d *Dir) {
		verb := "Reformatting"
		if !d.Cfg.GetBool("write") {
			verb = "Checking format of"
		}
		_ = write
		logInfof("%s %s", verb, d.Path)
		if d.hasLogicalSchemas() {
			if werr := acquireWorkspace(d); werr != nil {
				logErrorf("Skipping %s: %s", d.Path, werr.Error())
				resultCode = codeMax(resultCode, errorCode(werr, 2))
				return
			}
			return
		}
		if d.Depth >= 5 && len(d.SubdirNames) > 0 {
			logErrorf("Not walking subdirs of %s: max depth reached", d.Path)
			return
		}
		for _, name := range d.SubdirNames {
			sub, serr := parseOneSubdir(d, name, cfg)
			if serr != nil {
				logWarnf("Skipping %s: %s", filepath.Join(d.Path, name), serr.Error())
				resultCode = codeMax(resultCode, 78)
				continue
			}
			recurse(sub)
		}
	}
	recurse(base)
	return ExitOutcome{Code: resultCode, Err: fmt.Errorf(""), Logged: true}
}

// ---------------- Workspace ----------------
func acquireWorkspace(d *Dir) error {
	cfg := d.Cfg
	env := d.env
	ws := strings.ToLower(strings.TrimSpace(cfg.Get("workspace")))
	flavor := strings.TrimSpace(cfg.Get("flavor"))
	hostVal := hostForInstance(cfg)
	canTemp := ws != "docker" && hostVal != ""
	canDocker := ws == "docker" && flavor != ""
	if !canTemp && !canDocker {
		return newCodedError(78, "This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", env)
	}
	if ws == "docker" {
		if !cfg.Changed("docker-cleanup") {
			logDebugf("Upgrade notice: the --docker-cleanup option, which currently defaults to \"none\" in Skeema v1, will change to default to \"stop\" in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
		}
		if _, err := cfg.GetEnum("docker-cleanup", allOptDefs["docker-cleanup"].Valid); err != nil {
			return err
		}
		if !isKnownFlavor(flavor) {
			return fmt.Errorf("no flavor supplied")
		}
		if _, err := exec.LookPath("docker"); err != nil {
			return fmt.Errorf("unable to find `docker` command-line client among directories in PATH")
		}
		// Docker present: we cannot fully emulate container creation. Attempt `docker info`? For now generic.
		return fmt.Errorf("unable to find `docker` command-line client among directories in PATH")
	}
	// temp-schema (or bogus treated as temp for connection phase)
	schemaName := ""
	if len(d.LogicalSchemas) > 0 {
		schemaName = d.LogicalSchemas[0].Name
	}
	hosts, err := resolveHosts(cfg, d.Path, schemaName, env)
	if err != nil {
		return err
	}
	if len(hosts) == 0 {
		return newCodedError(78, "This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", env)
	}
	inst, err := buildInstance(cfg, d.Path, hosts[0])
	if err != nil {
		return err
	}
	if err := inst.connect(); err != nil {
		if _, ok := err.(*connectedButUnsupportedError); ok {
			return newCodedError(78, "Unable to connect to %s for %s: invalid connection", inst.Display, d.Path)
		}
		return newCodedError(78, "Unable to connect to %s for %s: %s", inst.Display, d.Path, err.Error())
	}
	return nil
}

func hostForInstance(cfg *Config) string {
	s, ok := cfg.winningSetting("host")
	if !ok {
		return ""
	}
	if s.Kind == SourceMyCnf {
		return ""
	}
	return strings.TrimSpace(cfg.Get("host"))
}

// ---------------- Diff/Push ----------------
func validateConcurrent(cfg *Config) error {
	raw := ""
	// alias takes precedence if changed
	if cfg.Changed("concurrent-instances") {
		raw = cfg.Get("concurrent-instances")
	} else {
		raw = cfg.Get("concurrent-servers")
	}
	n, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return newCodedError(78, "%s", err.Error())
	}
	if n < 1 {
		return newCodedError(78, "concurrent-instances cannot be less than 1")
	}
	return nil
}

func diffPushHandler(parsed *ParsedCLI, cfg *Config, isPush bool) ExitOutcome {
	if err := validateConcurrent(cfg); err != nil {
		return outcomeErr(errorCode(err, 78), err)
	}
	base, err := getBaseDir(parsed, cfg)
	if err != nil {
		return baseErrorOutcome(err)
	}
	env, _ := parsed.environmentArg()
	skipped := 0
	firstOnly := cfg.GetBool("first-only")
	var processDir func(d *Dir)
	var walk func(d *Dir)
	processDir = func(d *Dir) {
		// Determine candidacy
		// Special "other environments define schema" based on own OptionFile
		noSchemaOtherEnv := false
		if !d.HasSchemaCfg && d.OptionFile != nil {
			// schema in any section other than "" and env, and not in ""/env
			hasOther := false
			for _, sec := range d.OptionFile.Sections {
				if sec == "" || sec == env {
					continue
				}
				if d.OptionFile.HasOption(sec, "schema") {
					hasOther = true
				}
			}
			if hasOther && !d.OptionFile.HasOption("", "schema") && !d.OptionFile.HasOption(env, "schema") {
				// Also ensure parent files don't give schema (HasSchemaCfg would be true)
				noSchemaOtherEnv = true
			}
		}
		hasTarget := d.hasTargetsForDiff()
		if noSchemaOtherEnv && !hasTarget {
			logWarnf("Skipping %s: no schema defined for environment \"%s\"", d.Path, env)
			logWarnf("Other environments do define a schema name. Refer to the .skeema file in this directory for details.")
			return
		}
		if !hasTarget {
			return
		}
		// Candidate
		hostVal := hostForInstance(d.Cfg)
		if hostVal == "" {
			wrapper := strings.TrimSpace(d.Cfg.Get("host-wrapper"))
			logWarnf("Skipping %s: no host defined for environment \"%s\"", d.Path, env)
			if wrapper != "" {
				logWarnf("The host-wrapper option controls which hosts this directory maps to, but a .skeema file also needs to set the host option to some value (even just a placeholder value) for this command to properly map directories to hosts and schemas.")
			} else {
				logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
			}
			return
		}
		schemaName := ""
		// first named LS or config schema
		if d.HasSchemaCfg {
			schemaName = d.Cfg.Get("schema")
		} else {
			for _, ls := range d.LogicalSchemas {
				if ls.Name != "" {
					schemaName = ls.Name
					break
				}
			}
		}
		hosts, err := resolveHosts(d.Cfg, d.Path, schemaName, env)
		if err != nil {
			logErrorf("Skipping %s: %s", d.Path, err.Error())
			skipped++
			return
		}
		if len(hosts) == 0 {
			logWarnf("Skipping %s: directory maps to an empty list of database servers", d.Path)
			logWarnf("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
			return
		}
		// Build all instances first; a build error aborts this dir with one skipped op
		var insts []*Instance
		for _, h := range hosts {
			inst, berr := buildInstance(d.Cfg, d.Path, h)
			if berr != nil {
				logErrorf("Skipping %s: %s", d.Path, berr.Error())
				skipped++
				return
			}
			insts = append(insts, inst)
		}
		for idx, inst := range insts {
			if firstOnly && idx > 0 {
				break
			}
			if err := inst.connect(); err != nil {
				if _, ok := err.(*connectedButUnsupportedError); ok {
					logErrorf("Skipping %s for %s: invalid connection", inst.Display, d.Path)
				} else {
					logErrorf("Skipping %s for %s: %s", inst.Display, d.Path, err.Error())
				}
				skipped++
			}
		}
	}
	walk = func(d *Dir) {
		processDir(d)
		if d.Depth >= 5 && len(d.SubdirNames) > 0 {
			logWarnf("Skipping subdirs of %s: max depth reached", d.Path)
			skipped++
			return
		}
		for _, name := range d.SubdirNames {
			sub, serr := parseOneSubdir(d, name, cfg)
			if serr != nil {
				logErrorf("Skipping %s: %s", filepath.Join(d.Path, name), serr.Error())
				skipped++
				continue
			}
			walk(sub)
		}
	}
	walk(base)
	if skipped > 0 {
		op := "operation"
		prob := "problem"
		if skipped != 1 {
			op = "operations"
			prob = "problems"
		}
		logErrorf("Skipped %d %s due to %s", skipped, op, prob)
		return ExitOutcome{Code: 2, Err: fmt.Errorf(""), Logged: true}
	}
	return outcomeSuccess()
}

// ---------------- Pull ----------------
func pullHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	upgradeFormatNotice(cfg)
	base, err := getBaseDir(parsed, cfg)
	if err != nil {
		return baseErrorOutcome(err)
	}
	env, _ := parsed.environmentArg()
	resultCode := 0
	var process func(d *Dir)
	process = func(d *Dir) {
		hostVal := hostForInstance(d.Cfg)
		if hostVal != "" {
			schemaName := d.Cfg.Get("schema")
			hosts, herr := resolveHosts(d.Cfg, d.Path, schemaName, env)
			if herr != nil {
				logWarnf("Skipping %s: %s", d.Path, herr.Error())
				resultCode = codeMax(resultCode, 1)
				return
			}
			if len(hosts) == 0 {
				// treat as no host below
			} else {
				// build all
				var insts []*Instance
				for _, h := range hosts {
					inst, berr := buildInstance(d.Cfg, d.Path, h)
					if berr != nil {
						logWarnf("Skipping %s: %s", d.Path, berr.Error())
						resultCode = codeMax(resultCode, 1)
						return
					}
					insts = append(insts, inst)
				}
				for _, inst := range insts {
					if err := inst.connect(); err != nil {
						if _, ok := err.(*connectedButUnsupportedError); ok {
							logWarnf("Skipping %s: Unable to connect to %s for %s: invalid connection", d.Path, inst.Display, d.Path)
						} else {
							logWarnf("Skipping %s: Unable to connect to %s for %s: %s", d.Path, inst.Display, d.Path, err.Error())
						}
						resultCode = codeMax(resultCode, 1)
					}
				}
				return
			}
		}
		// No host: if candidate, error
		if d.hasTargetsForDiff() {
			wrapper := strings.TrimSpace(d.Cfg.Get("host-wrapper"))
			logErrorf("Skipping %s: No host defined for environment \"%s\"", d.Path, env)
			if wrapper != "" {
				// Original pulls executes script and reports empty; approximate
				logErrorf("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
			} else {
				logErrorf("This command requires a hostname to pull from, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
			}
			resultCode = codeMax(resultCode, 78)
			return
		}
		// descend
		if d.Depth >= 5 && len(d.SubdirNames) > 0 {
			logErrorf("Not walking subdirs of %s: max depth reached", d.Path)
			resultCode = codeMax(resultCode, 1)
			return
		}
		for _, name := range d.SubdirNames {
			sub, serr := parseOneSubdir(d, name, cfg)
			if serr != nil {
				logWarnf("Skipping %s: %s", filepath.Join(d.Path, name), serr.Error())
				resultCode = codeMax(resultCode, 78)
				continue
			}
			process(sub)
		}
	}
	process(base)
	return ExitOutcome{Code: resultCode, Err: fmt.Errorf(""), Logged: true}
}

// ---------------- Init ----------------
func validEnvName(s string) bool {
	if s == "" {
		return false
	}
	if strings.ContainsAny(s, "[]\n\r") {
		return false
	}
	return true
}

func initHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	env, _ := parsed.environmentArg()
	if !validEnvName(env) {
		return outcomeErr(78, fmt.Errorf("Environment name \"%s\" is invalid", env))
	}
	if !cfg.OnCLI("host") {
		return outcomeErr(78, fmt.Errorf("Option --host must be supplied on the command-line"))
	}
	dirVal := ""
	if cfg.Changed("dir") {
		dirVal = cfg.Get("dir")
	} else {
		rawHost := strings.TrimSpace(cfg.Get("host"))
		portParsed := parsePort(cfg.Get("port"))
		// determine socket prelim
		isSocket := false
		if rawHost == "localhost" {
			if cfg.Changed("socket") || !cfg.Changed("port") {
				isSocket = true
			}
		}
		if isSocket {
			dirVal = rawHost
		} else if portParsed != 0 && portParsed != 3306 {
			dirVal = fmt.Sprintf("%s:%d", rawHost, portParsed)
		} else {
			dirVal = rawHost
		}
	}
	// mkdir
	if err := os.MkdirAll(dirVal, 0755); err != nil {
		return outcomeErr(73, fmt.Errorf("Cannot create dir %s: %s", dirVal, err.Error()))
	}
	cwd, _ := os.Getwd()
	targetAbs := dirVal
	if !filepath.IsAbs(targetAbs) {
		targetAbs = filepath.Join(cwd, dirVal)
	}
	targetAbs = absPath(targetAbs)
	dirObj, err := parseDir(targetAbs, cfg, env, targetAbs, 0, nil)
	if err != nil {
		return baseErrorOutcome(err)
	}
	if !cfg.OnCLI("schema") {
		// schema from file layers (global or dir ancestor) but not my.cnf
		if schemaFromFileLayers(dirObj.Cfg) {
			return outcomeErr(78, fmt.Errorf("Cannot use dir %s: an ancestor option file defines schema option", targetAbs))
		}
	}
	// Instances
	schemaName := cfg.Get("schema")
	hosts, herr := resolveHosts(dirObj.Cfg, targetAbs, schemaName, env)
	if herr != nil {
		return outcomeErr(errorCode(herr, 2), herr)
	}
	if len(hosts) == 0 {
		// host-wrapper gave none; approximate
		return outcomeErr(2, fmt.Errorf("directory maps to an empty list of database servers"))
	}
	inst, berr := buildInstance(dirObj.Cfg, targetAbs, hosts[0])
	if berr != nil {
		return outcomeErr(errorCode(berr, 2), berr)
	}
	if err := inst.connect(); err != nil {
		if _, ok := err.(*connectedButUnsupportedError); ok {
			return outcomeErr(2, fmt.Errorf("Unable to connect to %s for %s: invalid connection", inst.Display, targetAbs))
		}
		return outcomeErr(2, fmt.Errorf("Unable to connect to %s for %s: %s", inst.Display, targetAbs, err.Error()))
	}
	return outcomeSuccess()
}

func schemaFromFileLayers(cfg *Config) bool {
	for _, layer := range cfg.layers {
		if s, ok := layer.settings["schema"]; ok {
			if s.Kind == SourceGlobalFile || s.Kind == SourceDirFile {
				return true
			}
		}
	}
	return false
}

// ---------------- Add-Environment ----------------
func addEnvironmentHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	envNew := ""
	if len(parsed.Args) > 0 {
		envNew = strings.TrimSpace(parsed.Args[0])
		// Note: original preserves internal spaces; leading/trailing trimmed via TrimSpace above.
		// But if arg had leading/trailing spaces intentionally for section [ x ], trimming may differ - acceptable.
	}
	dirVal := cfg.Get("dir")
	// Stat dir
	info, err := os.Stat(dirVal)
	if err != nil {
		return outcomeErr(78, fmt.Errorf("In add-environment, --dir must refer to a directory that already exists"))
	}
	if !info.IsDir() {
		return outcomeErr(78, fmt.Errorf("--dir=%s already exists but is not a directory", dirVal))
	}
	absDir := absPath(dirVal)
	skeemaPath := filepath.Join(absDir, ".skeema")
	if _, err := os.Stat(skeemaPath); err != nil {
		if os.IsNotExist(err) {
			return outcomeErr(78, fmt.Errorf("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", absDir))
		}
		return outcomeErr(errorCode(err, 2), err)
	}
	of, err := loadDirOptionFile(skeemaPath)
	if err != nil {
		return outcomeErr(errorCode(err, 2), err)
	}
	of.warnDeprecated()
	if !cfg.OnCLI("host") {
		return outcomeErr(78, fmt.Errorf("`skeema add-environment` requires --host to be supplied on command-line"))
	}
	if !validEnvName(envNew) {
		return outcomeErr(78, fmt.Errorf("Environment name \"%s\" is invalid", envNew))
	}
	if of.HasSection(envNew) && envNew != "" {
		// Section "" is not an env; but envNew non-empty here.
		// Ensure section actually appeared (Sections list includes only ensures; HasSection checks Values map)
		return outcomeErr(78, fmt.Errorf("Environment name \"%s\" already defined in %s", envNew, skeemaPath))
	}
	if !of.HasOptionAnySection("host") {
		return outcomeErr(78, fmt.Errorf("This command should be run against a --dir whose .skeema file already defines a host for another environment"))
	}
	rawHost := strings.TrimSpace(cfg.Get("host"))
	hostPart, portInHost, _ := splitHost(rawHost)
	hostName := hostPart
	if hostName == "" {
		hostName = rawHost
	}
	// Flavor determination attempt (ignore errors, warn)
	flavorKnown := attemptFlavor(cfg, absDir)
	if flavorKnown == "" {
		logWarnf("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", skeemaPath)
	}
	// Write new section
	of.ensureSection(envNew)
	of.Set(envNew, "host", hostName)
	if hostName == "localhost" {
		sock := strings.TrimSpace(cfg.Get("socket"))
		if sock == "" {
			sock = "/tmp/mysql.sock"
		}
		of.Set(envNew, "socket", sock)
		// Remove port if present in new section (it won't be)
	} else {
		port := 3306
		if portInHost != "" {
			if p := parsePort(portInHost); p != 0 {
				port = p
			}
		} else if p := parsePort(cfg.Get("port")); p != 0 {
			port = p
		}
		of.Set(envNew, "port", strconv.Itoa(port))
	}
	if flavorKnown != "" {
		of.Set(envNew, "flavor", flavorKnown)
	}
	content := of.Write()
	// Preserve file mode if possible
	mode := os.FileMode(0644)
	if fi, err := os.Stat(skeemaPath); err == nil {
		mode = fi.Mode()
	}
	if err := os.WriteFile(skeemaPath, []byte(content), mode); err != nil {
		return outcomeErr(errorCode(err, 2), err)
	}
	logInfof("Added environment [%s] to %s", envNew, skeemaPath)
	return outcomeSuccess()
}

func attemptFlavor(cfg *Config, dirPath string) string {
	// Build instance and try connect; ignore errors.
	hosts, err := resolveHosts(cfg, dirPath, "", "")
	if err != nil || len(hosts) == 0 {
		return ""
	}
	inst, err := buildInstance(cfg, dirPath, hosts[0])
	if err != nil {
		return ""
	}
	err = inst.connect()
	if err != nil {
		if ce, ok := err.(*connectedButUnsupportedError); ok {
			return flavorFromServerVersion(ce.serverVersion)
		}
		return ""
	}
	return ""
}

func flavorFromServerVersion(v string) string {
	// Very rough: "8.0.36" -> mysql:8.0, "10.11.x-MariaDB" -> mariadb:10.11
	lv := strings.ToLower(v)
	vendor := "mysql"
	if strings.Contains(lv, "mariadb") {
		vendor = "mariadb"
	} else if strings.Contains(lv, "percona") {
		vendor = "percona"
	}
	// extract leading x.y
	parts := strings.FieldsFunc(v, func(r rune) bool { return r == '-' || r == ' ' })
	if len(parts) == 0 {
		return ""
	}
	ver := parts[0]
	nums := strings.Split(ver, ".")
	if len(nums) >= 2 {
		return vendor + ":" + nums[0] + "." + nums[1]
	}
	return ""
}
