func parseConnectOptions(s string) (map[string]string, error) {
	out := map[string]string{}
	s = strings.TrimSpace(s)
	if s == "" {
		return out, nil
	}
	// Validate comma placement and split respecting quotes, tracking byte offsets.
	type seg struct{ start, end int }
	var segs []seg
	inQuote := false
	var q byte
	segStart := 0
	prevComma := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == q {
				inQuote = false
			}
			prevComma = false
			continue
		}
		if c == '\'' || c == '"' {
			inQuote = true
			q = c
			prevComma = false
			continue
		}
		if c == ',' {
			if i == 0 || prevComma || i == len(s)-1 {
				return nil, fmt.Errorf("Invalid comma placement in option value at byte offset %d in connect-options \"%s\"", i, s)
			}
			segs = append(segs, seg{segStart, i})
			segStart = i + 1
			prevComma = true
		} else if c != ' ' && c != '\t' {
			prevComma = false
		}
	}
	segs = append(segs, seg{segStart, len(s)})
	for _, sg := range segs {
		part := s[sg.start:sg.end]
		eq := strings.Index(part, "=")
		if eq < 0 {
			return nil, fmt.Errorf("Option %s is missing a value at byte offset %d in connect-options \"%s\"", strings.TrimSpace(part), sg.end, s)
		}
		if eq == 0 {
			// Observed "=x" reports Option x is missing a value
			return nil, fmt.Errorf("Option %s is missing a value at byte offset %d in connect-options \"%s\"", strings.TrimSpace(part[1:]), sg.end, s)
		}
		if eq == len(part)-1 {
			return nil, fmt.Errorf("Invalid comma placement in option value at byte offset %d in connect-options \"%s\"", sg.end, s)
		}
		k := part[:eq]
		v := part[eq+1:]
		out[k] = v
	}
	return out, nil
}

