package main

import "fmt"

type mysqlError struct {
	Code  int
	State string
	Msg   string
}

func (e *mysqlError) Error() string {
	if e.State != "" {
		return fmt.Sprintf("Error %d (%s): %s", e.Code, e.State, e.Msg)
	}
	return fmt.Sprintf("Error %d: %s", e.Code, e.Msg)
}

func maybeLogPasswordHint(cfg *Config, err error) {
	me, ok := err.(*mysqlError)
	if !ok {
		return
	}
	if me.Code == 1045 && cfg != nil && cfg.Get("password") == "" {
		logErrorf("No password was supplied for this login attempt, but the server likely requires a password. For information on how to use Skeema's password option, see https://www.skeema.io/docs/options/#password")
	}
}

// workspaceError wraps an error with exit code and an optional underlying mysql error for hint.
type workspaceError struct {
	code int
	msg  string
	under error
}

func (e *workspaceError) Error() string { return e.msg }
