func mysqlDriverLog(format string, args ...any) {
	// go-sql-driver/mysql uses standard log package with [mysql] prefix
	ts := time.Now().Format("2006/01/02 15:04:05")
	fmt.Fprintf(os.Stderr, "[mysql] %s "+format+"\n", append([]any{ts}, args...)...)
}

func readMySQLPacket(conn net.Conn, expectedSeq byte) ([]byte, error) {
	header := make([]byte, 4)
	if _, err := readFull(conn, header); err != nil {
		mysqlDriverLog("packets.go:58 unexpected EOF")
		return nil, fmt.Errorf("invalid connection")
	}
	length := int(uint32(header[0]) | uint32(header[1])<<8 | uint32(header[2])<<16)
	seq := header[3]
	if seq != expectedSeq {
		mysqlDriverLog("packets.go:68 [warn] unexpected sequence nr: expected %d, got %d", expectedSeq, seq)
	}
	if length == 0 {
		return []byte{}, nil
	}
	// Cap allocation to avoid huge garbage lengths; driver attempts to read full body and logs unexpected EOF when server closes.
	// We'll read in chunks up to length but stop on error.
	payload := make([]byte, 0, min(length, 1024*1024))
	buf := make([]byte, 8192)
	remaining := length
