# replace lines 515-576 (index514-575) with reconstructed handlers
new=r'''func initHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	env, _ := parsed.environmentArg()
	if !validEnvName(env) {
		return outcomeErr(78, fmt.Errorf("Environment name \"%s\" is invalid", env))
	}
	if !cfg.OnCLI("host") {
		return outcomeErr(78, fmt.Errorf("Option --host must be supplied on the command-line"))
	}
	dirVal := ""
	if cfg.Changed("dir") {
		dirVal = cfg.Get("dir")
	} else {
		rawHost := strings.TrimSpace(cfg.Get("host"))
		portParsed := parsePort(cfg.Get("port"))
		if portParsed != 0 && portParsed != 3306 {
			dirVal = fmt.Sprintf("%s:%d", rawHost, portParsed)
		} else {
			dirVal = rawHost
		}
	}
	if err := os.MkdirAll(dirVal, 0755); err != nil {
		return outcomeErr(73, fmt.Errorf("Cannot create dir %s: %s", dirVal, err.Error()))
	}
	cwd, _ := os.Getwd()
	targetAbs := dirVal
	if !filepath.IsAbs(targetAbs) {
		targetAbs = filepath.Join(cwd, dirVal)
	}
	targetAbs = absPath(targetAbs)
	dirObj, err := parseDir(targetAbs, cfg, env, targetAbs, 0, nil)
	if err != nil {
		return baseErrorOutcome(err)
	}
	if !cfg.OnCLI("schema") {
		if schemaFromFileLayers(dirObj.Cfg) {
			return outcomeErr(78, fmt.Errorf("Cannot use dir %s: an ancestor option file defines schema option", targetAbs))
		}
	}
	schemaName := cfg.Get("schema")
	hosts, herr := resolveHosts(dirObj.Cfg, targetAbs, schemaName, env)
	if herr != nil {
		return outcomeErr(errorCode(herr, 2), herr)
	}
	if len(hosts) == 0 {
		return outcomeErr(78, fmt.Errorf("Command line did not specify which database server to connect to"))
	}
	// Build all instances; init tries each until one connects.
	var insts []*Instance
	for _, h := range hosts {
		inst, berr := buildInstance(dirObj.Cfg, targetAbs, h)
		if berr != nil {
			return outcomeErr(errorCode(berr, 2), berr)
		}
		insts = append(insts, inst)
	}
	var lastErr error
	for _, inst := range insts {
		if err := inst.connect(); err != nil {
			if _, ok := err.(*connectedButUnsupportedError); ok {
				logErrorf("Unable to connect to %s for %s: invalid connection", inst.Display, targetAbs)
				return ExitOutcome{Code: 2, Err: fmt.Errorf(""), Logged: true}
			}
			lastErr = err
		} else {
			return outcomeSuccess()
		}
	}
	if len(insts) == 1 {
		logErrorf("Unable to connect to %s for %s: %s", insts[0].Display, targetAbs, lastErr.Error())
		maybeLogPasswordHint(dirObj.Cfg, lastErr)
		return ExitOutcome{Code: 2, Err: fmt.Errorf(""), Logged: true}
	}
	logErrorf("Unable to connect to any of %d database servers for %s; last error %s", len(insts), targetAbs, lastErr.Error())
	maybeLogPasswordHint(dirObj.Cfg, lastErr)
	return ExitOutcome{Code: 2, Err: fmt.Errorf(""), Logged: true}
}

func schemaFromFileLayers(cfg *Config) bool {
	for _, layer := range cfg.layers {
		if s, ok := layer.settings["schema"]; ok {
			if s.Kind == SourceGlobalFile || s.Kind == SourceDirFile {
				return true
			}
		}
	}
	return false
}

// ---------------- Add-Environment ----------------
func addEnvironmentHandler(parsed *ParsedCLI, cfg *Config) ExitOutcome {
	envNew := ""
	if len(parsed.Args) > 0 {
		envNew = strings.TrimSpace(parsed.Args[0])
