{"command":"cat > flavor.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type Flavor struct {
	Vendor string // mysql, mariadb, percona, unknown
	Major  int
	Minor  int
	Known  bool // vendor recognized
}

func parseFlavor(s string) Flavor {
	s = strings.TrimSpace(s)
	if s == "" {
		return Flavor{Vendor: "unknown"}
	}
	vendorStr := s
	verStr := ""
	if idx := strings.Index(s, ":"); idx >= 0 {
		vendorStr = s[:idx]
		verStr = s[idx+1:]
	}
	f := Flavor{Vendor: "unknown"}
	switch vendorStr {
	case "mysql", "mariadb", "percona":
		f.Vendor = vendorStr
		f.Known = true
	}
	if verStr != "" {
		parts := strings.Split(verStr, ".")
		if len(parts) > 0 {
			f.Major = leadingInt(parts[0])
		}
		if len(parts) > 1 {
			f.Minor = leadingInt(parts[1])
		}
	}
	return f
}
func leadingInt(s string) int {
	s = strings.TrimSpace(s)
	n := 0
	seen := false
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			seen = true
			n = n*10 + int(s[i]-'0')
		} else {
			break
		}
	}
	if !seen {
		return 0
	}
	// use strconv for completeness on the digit prefix
	_ = strconv.Itoa
	return n
}
func (f Flavor) String() string { return fmt.Sprintf("%s:%d.%d", f.Vendor, f.Major, f.Minor) }
func (f Flavor) IsZero() bool { return !f.Known && f.Major == 0 && f.Minor == 0 }
func (f Flavor) Recognized() bool {
	return f.Known && (f.Major != 0 || f.Minor != 0)
}
func (f Flavor) versionAtLeast(maj, min int) bool {
	return f.Major > maj || (f.Major == maj && f.Minor >= min)
}
func (f Flavor) UnsupportedError() error {
	if f.Major == 0 && f.Minor == 0 {
		return nil
	}
	if (f.Vendor == "mysql" || f.Vendor == "percona") && !f.versionAtLeast(5, 5) {
		return fmt.Errorf("MySQL %d.%d is not supported by Skeema.", f.Major, f.Minor)
	}
	if f.Vendor == "mariadb" && !f.versionAtLeast(10, 1) {
		return fmt.Errorf("MariaDB %d.%d is not supported by Skeema.", f.Major, f.Minor)
	}
	return nil
}
EOF
