{"command":"cat > helpformat.go <<'EOF'
package main

import (
	"os"
	"regexp"
	"strings"
	"syscall"
	"unsafe"
)

func terminalWidth() int {
	if !isTTY(os.Stdout) {
		return 80
	}
	type winsize struct {
		Rows, Cols, X, Y uint16
	}
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 || ws.Cols == 0 {
		return 80
	}
	if int(ws.Cols) < 80 {
		return 80
	}
	return int(ws.Cols)
}

var optSpecRe = regexp.MustCompile(`^(  -\S, --\S+(?:\[=value\]| value)?|      --\S+(?:\[=value\]| value)?)`)

func wrapText(text string, width int) []string {
	if width <= 0 {
		return []string{text}
	}
	words := strings.Fields(text)
	if len(words) == 0 {
		return []string{""}
	}
	var lines []string
	cur := words[0]
	for _, w := range words[1:] {
		if len(cur)+1+len(w) <= width {
			cur += " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	lines = append(lines, cur)
	return lines
}

func computeDescCol(lines []string) int {
	// Use continuation indents if present
	counts := map[int]int{}
	for _, line := range lines {
		if strings.HasPrefix(line, "                                   ") {
			n := 0
			for n < len(line) && line[n] == ' ' {
				n++
			}
			if n < len(line) {
				counts[n]++
			}
		}
	}
	best, bestN := 0, 0
	for n, c := range counts {
		if c > bestN || (c == bestN && n < best) {
			best, bestN = n, c
		}
	}
	if best > 0 {
		return best
	}
	maxSpec := 0
	for _, line := range lines {
		if m := optSpecRe.FindString(line); m != "" && len(m)+2 > maxSpec {
			maxSpec = len(m) + 2
		}
	}
	if maxSpec == 0 {
		return 30
	}
	return maxSpec
}

func formatHelp(static string) string {
	width := terminalWidth()
	if width == 80 {
		return static
	}
	lines := strings.Split(static, "\n")
	descCol := computeDescCol(lines)
	var out []string
	i := 0
	// Preserve leading blank and Usage line and following blank
	// General state machine
	mode := "prose" // prose, entries, footer
	for i < len(lines) {
		line := lines[i]
		if strings.HasPrefix(line, "Complete documentation") {
			mode = "footer"
		}
		if mode == "footer" {
			out = append(out, line)
			i++
			continue
		}
		if line == "" {
			out = append(out, "")
			i++
			continue
		}
		if strings.HasPrefix(line, "Usage:") {
			out = append(out, line)
			i++
			continue
		}
		if line == "Commands:" || strings.HasSuffix(line, " Options:") {
			mode = "entries"
			out = append(out, line)
			i++
			continue
		}
		if mode == "entries" {
			// Parse one entry
			if m := optSpecRe.FindString(line); m != "" || (strings.HasPrefix(line, "      ") && !strings.HasPrefix(strings.TrimSpace(line), "--")) {
				// Command entries in root don't match optSpecRe: "      name  desc"
				if m == "" {
					// Treat entire line as already formatted if short, else parse command entry
					trim := strings.TrimSpace(line)
					// split into name and desc at 2+ spaces
					parts := regexp.MustCompile(`\s{2,}`).Split(trim, 2)
					if len(parts) == 2 {
						spec := "      " + parts[0]
						desc := parts[1]
						// command desc col fixed at 23 in root
						ccol := 23
						wrapped := wrapText(desc, width-ccol)
						for j, w := range wrapped {
							if j == 0 {
								out = append(out, spec+strings.Repeat(" ", ccol-len(spec))+w)
							} else {
								out = append(out, strings.Repeat(" ", ccol)+w)
							}
						}
					} else {
						out = append(out, line)
					}
					i++
					continue
				}
				spec := m
				desc := strings.TrimSpace(line[len(m):])
				i++
				// continuations
				for i < len(lines) {
					nl := lines[i]
					if nl == "" || optSpecRe.MatchString(nl) || strings.HasPrefix(nl, "Complete documentation") || nl == "Commands:" || strings.HasSuffix(nl, " Options:") {
						break
					}
					// continuation lines are heavily indented
					if len(nl) > descCol && strings.TrimSpace(nl[:descCol]) == "" {
						desc += " " + strings.TrimSpace(nl)
						i++
						continue
					}
					break
				}
				wrapped := wrapText(desc, width-descCol)
				for j, w := range wrapped {
					if j == 0 {
						prefix := spec
						if len(prefix) < descCol {
							prefix += strings.Repeat(" ", descCol-len(prefix))
						} else {
							prefix += "  "
						}
						out = append(out, prefix+w)
					} else {
						out = append(out, strings.Repeat(" ", descCol)+w)
					}
				}
				continue
			}
			// Fallback: preserve line
			out = append(out, line)
			i++
			continue
		}
		// Prose paragraph: gather until blank
		var para []string
		for i < len(lines) && lines[i] != "" && !strings.HasPrefix(lines[i], "Complete documentation") && lines[i] != "Commands:" && !strings.HasSuffix(lines[i], " Options:") {
			para = append(para, strings.TrimSpace(lines[i]))
			i++
		}
		text := strings.Join(para, " ")
		out = append(out, wrapText(text, width)...)
	}
	return strings.Join(out, "\n")
}
