{"command":"cat > docker.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

var dockerArchCache string
var dockerInfoOK bool

func dockerCmd(args ...string) (string, error) {
	path, err := exec.LookPath("docker")
	if err != nil {
		return "", fmt.Errorf("unable to find `docker` command-line client among directories in PATH")
	}
	cmd := exec.Command(path, args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		code := 2
		if ee, ok := err.(*exec.ExitError); ok {
			code = ee.ExitCode()
		}
		return stdout.String(), &workspaceError{code: code, msg: fmt.Sprintf("%s: %s", err.Error(), strings.TrimSuffix(stderr.String(), "\n")), under: err}
	}
	return stdout.String(), nil
}

func dockerInfoCmd() error {
	path, err := exec.LookPath("docker")
	if err != nil {
		return fmt.Errorf("unable to find `docker` command-line client among directories in PATH")
	}
	cmd := exec.Command(path, "info", "--format", "{{json .}}")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		code := 2
		if ee, ok := err.(*exec.ExitError); ok {
			code = ee.ExitCode()
		}
		return &workspaceError{code: code, msg: fmt.Sprintf("error invoking `docker` command-line client: %s: %s", err.Error(), strings.TrimSuffix(stderr.String(), "\n")), under: err}
	}
	var v map[string]any
	if err := json.NewDecoder(&stdout).Decode(&v); err != nil {
		return &workspaceError{code: 2, msg: fmt.Sprintf("error decoding JSON response from `docker` command-line client: %s", err.Error()), under: err}
	}
	dockerInfoOK = true
	if arch, ok := v["Architecture"].(string); ok && arch != "" {
		dockerArchCache = arch
	}
	return nil
}

func ensureDockerArch() error {
	if dockerArchCache != "" {
		return nil
	}
	return dockerInfoCmd()
}

func flavorImage(fl Flavor) string {
	s := fl.String()
	if fl.Vendor == "percona" && fl.versionAtLeast(8, 0) {
		return fmt.Sprintf("percona/percona-server:%d.%d", fl.Major, fl.Minor)
	}
	return s
}
func flavorContainerName(fl Flavor) string { return "skeema-" + fl.String() }

func findDockerPort(container string) (int, error) {
	var lastDecodeErr error
	for attempt := 0; attempt < 5; attempt++ {
		out, err := dockerCmd("inspect", "--type", "container", "--format={{json .NetworkSettings.Ports}}", container)
		if err != nil {
			continue
		}
		var ports map[string][]map[string]string
		if err := json.Unmarshal([]byte(strings.TrimSpace(out)), &ports); err != nil {
			lastDecodeErr = fmt.Errorf("unable to decode JSON response from `docker` command-line client: %s", err.Error())
			continue
		}
		if arr, ok := ports["3306/tcp"]; ok && len(arr) > 0 {
			if hp, ok := arr[0]["HostPort"]; ok && hp != "" {
				if n, err := strconv.Atoi(hp); err == nil {
					return n, nil
				}
			}
		}
	}
	if lastDecodeErr != nil {
		return 0, fmt.Errorf("Unable to find port mapping for container %s: %s", container, lastDecodeErr.Error())
	}
	return 0, fmt.Errorf("Unable to find port mapping for container %s", container)
}

func acquireDockerWorkspace(d *Dir, fl Flavor) error {
	if err := dockerInfoCmd(); err != nil {
		return err
	}
	if err := ensureDockerArch(); err != nil {
		return err
	}
	container := flavorContainerName(fl)
	image := flavorImage(fl)
	logInfof("Using container %s (image=%s) for workspace operations", container, image)
	_, startErr := dockerCmd("start", container)
	var port int
	var portErr error
	if startErr == nil {
		port, portErr = findDockerPort(container)
		if portErr == nil {
			return connectDockerPort(d, port)
		}
	}
	// Try to create container
	if err := ensureDockerArch(); err != nil {
		if startErr != nil {
			return startErr
		}
		return portErr
	}
	runArgs := []string{"run", "-d", "-p", "127.0.0.1::3306/tcp", "-e", "MYSQL_ROOT_HOST=%", "-e", "LANG=C.UTF-8", "-e", "MYSQL_ALLOW_EMPTY_PASSWORD=1", "--name", container, image,
		"--loose-innodb-redo-log-capacity=8388608", "--loose-innodb-log-file-size=4194304", "--innodb-buffer-pool-size=33554432", "--performance-schema=0", "--skip-innodb-adaptive-hash-index", "--loose-innodb-log-writer-threads=off", "--loose-query-cache-size=0", "--skip-innodb-doublewrite", "--skip-log-bin"}
	_, runErr := dockerCmd(runArgs...)
	if runErr != nil {
		if startErr != nil {
			return startErr
		}
		if portErr != nil {
			// Original returns the earlier port-mapping failure when the subsequent run also fails
			if _, ok := portErr.(*workspaceError); ok {
				return portErr
			}
			return &workspaceError{code: 2, msg: portErr.Error(), under: portErr}
		}
		return runErr
	}
	port, portErr = findDockerPort(container)
	if portErr != nil {
		if startErr != nil {
			return startErr
		}
		if _, ok := portErr.(*workspaceError); ok {
			return portErr
		}
		return &workspaceError{code: 2, msg: portErr.Error(), under: portErr}
	}
	return connectDockerPort(d, port)
}

func connectDockerPort(d *Dir, port int) error {
	// Build a synthetic instance for the container
	cfg := d.Cfg.clone()
	cfg.setCLI("host", "127.0.0.1", false)
	cfg.setCLI("port", strconv.Itoa(port), false)
	cfg.setCLI("user", "root", false)
	cfg.setCLI("password", "", false)
	inst, err := buildInstance(cfg, d.Path, "127.0.0.1")
	if err != nil {
		return err
	}
	// Original waits for the server to become ready; retry briefly.
	deadline := time.Now().Add(30 * time.Second)
	for {
		err = inst.connect()
		if err == nil {
			return nil
