{"command":"cat > mysqlauth.go <<'EOF'
package main

import (
	"bytes"
	"crypto/sha1"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"net"
	"strings"
)

func parseHandshake(payload []byte) (salt []byte, plugin string, serverVer string, err error) {
	if len(payload) < 1 || payload[0] != 10 {
		return nil, "", "", fmt.Errorf("invalid connection")
	}
	rest := payload[1:]
	end := bytes.IndexByte(rest, 0)
	if end < 0 {
		return nil, "", "", fmt.Errorf("invalid connection")
	}
	serverVer = string(rest[:end])
	rest = rest[end+1:]
	// connection id 4, salt part1 8, filler1, cap lower2, charset1, status2, cap upper2, authDataLen1, reserved10
	if len(rest) < 4+8+1+2+1+2+2+1+10 {
		return nil, "", serverVer, fmt.Errorf("invalid connection")
	}
	salt = append(salt, rest[4:12]...)
	authLen := int(rest[4+8+1+2+1+2+2])
	rest = rest[4+8+1+2+1+2+2+1+10:]
	part2Len := 13
	if authLen-8 > part2Len {
		part2Len = authLen - 8
	}
	// part2 is at most remaining up to plugin name; null terminated
	if len(rest) > 0 {
		n := part2Len
		if n > len(rest) {
			n = len(rest)
		}
		part2 := rest[:n]
		// strip trailing NUL
		if idx := bytes.IndexByte(part2, 0); idx >= 0 {
			part2 = part2[:idx]
		}
		salt = append(salt, part2...)
		rest = rest[n:]
	}
	if len(rest) > 0 {
		plugin = strings.TrimRight(string(rest), "\x00")
	}
	if plugin == "" {
		plugin = "mysql_native_password"
	}
	return salt, plugin, serverVer, nil
}

func authResponse(plugin, password string, salt []byte) []byte {
	if password == "" {
		return []byte{}
	}
	switch plugin {
	case "mysql_native_password":
		h1 := sha1.Sum([]byte(password))
		h2 := sha1.Sum(h1[:])
		var buf bytes.Buffer
		buf.Write(salt)
		buf.Write(h2[:])
		h3 := sha1.Sum(buf.Bytes())
		out := make([]byte, len(h1))
		for i := range h1 {
			out[i] = h1[i] ^ h3[i]
		}
		return out
	case "caching_sha2_password":
		h1 := sha256.Sum256([]byte(password))
		h2 := sha256.Sum256(h1[:])
		var buf bytes.Buffer
		buf.Write(h2[:])
		buf.Write(salt)
		h3 := sha256.Sum256(buf.Bytes())
		out := make([]byte, len(h1))
		for i := range h1 {
			out[i] = h1[i] ^ h3[i]
		}
		return out
	case "mysql_clear_password":
		return append([]byte(password), 0)
	case "sha256_password":
		// Without TLS/RSA we cannot do full auth; send public key request marker as driver would for non-empty?
		return []byte{1}
	default:
		// unknown plugin - driver logs and fails after; return empty
		return []byte{}
	}
}

func writePacket(conn net.Conn, seq byte, payload []byte) error {
	hdr := []byte{byte(len(payload)), byte(len(payload) >> 8), byte(len(payload) >> 16), seq}
	if _, err := conn.Write(hdr); err != nil {
		return err
	}
	_, err := conn.Write(payload)
	return err
}

func doMySQLAuth(conn net.Conn, inst *Instance, handshake []byte) error {
	salt, plugin, serverVer, err := parseHandshake(handshake)
	if err != nil {
		return err
	}
	inst.flavor = serverVer
	password := inst.cfg.Get("password")
	user := inst.cfg.Get("user")
	const (
		clientLongPassword     = 0x00000001
		clientLongFlag         = 0x00000004
		clientProtocol41       = 0x00000200
		clientTransactions     = 0x00002000
		clientSecureConnection = 0x00008000
		clientMultiResults     = 0x00020000
		clientPSMultiResults   = 0x00040000
		clientPluginAuth       = 0x00080000
		clientConnectAttrs     = 0x00100000
		clientLenencData       = 0x00200000
		clientDeprecateEOF     = 0x01000000
	)
	flags := uint32(clientLongPassword | clientLongFlag | clientProtocol41 | clientTransactions | clientSecureConnection | clientMultiResults | clientPSMultiResults | clientPluginAuth | clientLenencData | clientDeprecateEOF)
	seq := byte(1)
	sendAuth := func(respPlugin string, resp []byte) error {
		var buf bytes.Buffer
		_ = binary.Write(&buf, binary.LittleEndian, flags)
		_ = binary.Write(&buf, binary.LittleEndian, uint32(67108864))
		buf.WriteByte(45) // utf8mb4_general_ci
		buf.Write(make([]byte, 23))
		buf.WriteString(user)
		buf.WriteByte(0)
		// lenenc auth response
		if len(resp) < 251 {
			buf.WriteByte(byte(len(resp)))
		} else {
			buf.WriteByte(0xfc)
			_ = binary.Write(&buf, binary.LittleEndian, uint16(len(resp)))
		}
		buf.Write(resp)
		buf.WriteString(respPlugin)
		buf.WriteByte(0)
		err := writePacket(conn, seq, buf.Bytes())
		seq++
		return err
	}
	if err := sendAuth(plugin, authResponse(plugin, password, salt)); err != nil {
		return err
	}
	for {
		payload, err := readMySQLPacket(conn, seq)
		if err != nil {
			return err
		}
		seq++
		if len(payload) == 0 {
			return fmt.Errorf("invalid connection")
		}
		switch payload[0] {
		case 0x00: // OK
			return &connectedButUnsupportedError{serverVersion: serverVer}
		case 0xff:
			return parseMySQLError(payload)
		case 0xfe: // auth switch request
